export const NAMES: AllahName[] = [
  { n: 1, ar: "الرَّحْمَٰنُ", tr: "Ar-Raḥmān", bn: "আর-রাহমান", en: "The Most Gracious", meaningBn: "পরম করুণাময়", detailBn: "‘রাহমান’ শব্দটি ‘রহমত’ থেকে এসেছে এবং এতে অসীম ও ব্যাপক করুণার অর্থ আছে। এ নামটি আল্লাহর জন্যই খাস; অন্য কাউকে ‘রাহমান’ বলা যায় না। দুনিয়ায় ভালো-মন্দ সবাই তাঁর রহমতের ছায়ায় বেঁচে আছে।", lessonBn: "আল্লাহর রহমতের আশা রাখুন এবং অন্যের প্রতিও দয়ালু হোন।", quran: [{"ref": "সূরা আল-ফাতিহা ১:৩", "ayat": ["1:3"], "gistBn": "আল্লাহ ‘আর-রাহমানির রাহীম’।"}, {"ref": "সূরা আর-রাহমান ৫৫:১-২", "ayat": ["55:1", "55:2"], "gistBn": "‘আর-রাহমান’ কুরআন শিক্ষা দিয়েছেন।"}], hadith: [{"src": "সহীহ মুসলিম ২৭৫২", "textBn": "আল্লাহ রহমতকে একশ ভাগ করেছেন। এক ভাগ দুনিয়ায় নাযিল করেছেন, যার কারণে সৃষ্টি পরস্পরের প্রতি দয়া করে। বাকি নিরানব্বই ভাগ কিয়ামতের জন্য রেখেছেন।"}] },
  { n: 2, ar: "الرَّحِيمُ", tr: "Ar-Raḥīm", bn: "আর-রাহীম", en: "The Most Merciful", meaningBn: "অতি দয়ালু", detailBn: "‘রাহীম’ অর্থ অতি দয়ালু। আলেমদের ব্যাখ্যায় ‘রাহমান’ হলো সবার প্রতি ব্যাপক রহমত, আর ‘রাহীম’ হলো মুমিনদের প্রতি বিশেষ রহমত, বিশেষ করে আখিরাতে।", lessonBn: "প্রতিটি ভালো কাজ ‘বিসমিল্লাহির রাহমানির রাহীম’ বলে শুরু করুন।", quran: [{"ref": "সূরা আল-আহযাব ৩৩:৪৩", "ayat": ["33:43"], "gistBn": "তিনি মুমিনদের প্রতি অতি দয়ালু।"}], hadith: [{"src": "সহীহ বুখারি ৫৯৯৯, সহীহ মুসলিম ২৭৫৪", "textBn": "বন্দিদের মধ্যে এক নারী তার শিশুকে বুকে জড়িয়ে নিলে নবী ﷺ সাহাবিদের বললেন, এই মা যেমন তার সন্তানের প্রতি দয়ালু, আল্লাহ তাঁর বান্দাদের প্রতি এর চেয়েও বেশি দয়ালু।"}] },
  { n: 3, ar: "الْمَلِكُ", tr: "Al-Malik", bn: "আল-মালিক", en: "The King", meaningBn: "সার্বভৌম অধিপতি", detailBn: "‘মালিক’ অর্থ রাজা ও অধিপতি। আল্লাহ শুধু নামে নয়, প্রকৃত অর্থেই সবকিছুর মালিক। মানুষের রাজত্ব সীমিত ও সাময়িক, আল্লাহর রাজত্ব চিরস্থায়ী ও পূর্ণ।", lessonBn: "ক্ষমতা ও সম্পদ আল্লাহর আমানত, এ কথা মনে রেখে বিনয়ী থাকুন।", quran: [{"ref": "সূরা আল-হাশর ৫৯:২৩", "ayat": ["59:23"], "gistBn": "তিনিই আল্লাহ, যিনি ছাড়া কোনো ইলাহ নেই; তিনি ‘আল-মালিক’।"}, {"ref": "সূরা আল-ফাতিহা ১:৪", "ayat": ["1:4"], "gistBn": "তিনি বিচার দিবসের মালিক।"}], hadith: [{"src": "সহীহ মুসলিম ২১৪৩", "textBn": "আল্লাহর কাছে সবচেয়ে নিকৃষ্ট নাম ‘রাজাধিরাজ’ উপাধি নেওয়া, কারণ প্রকৃত রাজাধিরাজ আল্লাহ ছাড়া কেউ নন।"}] },
  { n: 4, ar: "الْقُدُّوسُ", tr: "Al-Quddūs", bn: "আল-কুদ্দুস", en: "The Most Holy", meaningBn: "অতি পবিত্র", detailBn: "‘কুদ্দুস’ অর্থ সব দোষ-ত্রুটি, অপূর্ণতা ও সাদৃশ্য থেকে পবিত্র। সৃষ্টির কোনো দুর্বলতা আল্লাহকে স্পর্শ করে না। ফেরেশতারাও তাঁর পবিত্রতা ঘোষণা করেন।", lessonBn: "আল্লাহ সম্পর্কে ভালো ধারণা রাখুন এবং তাঁকে সৃষ্টির মতো ভাববেন না।", quran: [{"ref": "সূরা আল-জুমুআ ৬২:১", "ayat": ["62:1"], "gistBn": "আসমান ও জমিনের সবকিছু ‘আল-মালিকিল কুদ্দুস’-এর তাসবিহ পাঠ করে।"}], hadith: [{"src": "সহীহ মুসলিম ৪৮৭", "textBn": "নবী ﷺ রুকু ও সিজদায় বলতেন, ‘সুব্বুহুন কুদ্দুসুন রব্বুল মালাইকাতি ওয়ার রূহ’।"}] },
  { n: 5, ar: "السَّلَامُ", tr: "As-Salām", bn: "আস-সালাম", en: "The Source of Peace", meaningBn: "শান্তিদাতা", detailBn: "‘সালাম’ অর্থ শান্তি ও নিরাপত্তার উৎস। তিনি সব ত্রুটি থেকে মুক্ত এবং তাঁর কাছ থেকেই বান্দা শান্তি পায়। এ কারণে মুসলিমদের অভিবাদন ‘আস-সালামু আলাইকুম’ এবং জান্নাতের নাম ‘দারুস সালাম’।", lessonBn: "অন্তরের শান্তির জন্য আল্লাহর যিকিরে ফিরে আসুন এবং সালামের প্রচলন করুন।", quran: [{"ref": "সূরা আল-আনআম ৬:১২৭", "ayat": ["6:127"], "gistBn": "তাদের জন্য তাদের রবের কাছে ‘দারুস সালাম’ (শান্তির ঘর) আছে।"}], hadith: [{"src": "সহীহ মুসলিম ৫৯১", "textBn": "নামাজের সালামের পর নবী ﷺ বলতেন, ‘আল্লাহুম্মা আনতাস সালাম, ওয়া মিনকাস সালাম, তাবারাকতা ইয়া যাল জালালি ওয়াল ইকরাম’।"}] },
  { n: 6, ar: "الْمُؤْمِنُ", tr: "Al-Muʾmin", bn: "আল-মুমিন", en: "The Giver of Security", meaningBn: "নিরাপত্তাদাতা", detailBn: "‘মুমিন’ এখানে নিরাপত্তাদাতা ও সত্যায়নকারী। তিনি বান্দাকে ভয় থেকে নিরাপদ রাখেন এবং রাসূলদের সত্যতা প্রমাণ করেন। এই একই মূল থেকে ‘ঈমান’ শব্দ এসেছে।", lessonBn: "আল্লাহর কাছে নিরাপত্তা চান এবং অন্যের জন্য নিরাপদ হোন।", quran: [{"ref": "সূরা আল-হাশর ৫৯:২৩", "ayat": ["59:23"], "gistBn": "তিনিই ‘আল-মুমিন’, ‘আল-মুহাইমিন’।"}], hadith: [] },
  { n: 7, ar: "الْمُهَيْمِنُ", tr: "Al-Muhaymin", bn: "আল-মুহাইমিন", en: "The Guardian", meaningBn: "রক্ষক ও তত্ত্বাবধায়ক", detailBn: "‘মুহাইমিন’ অর্থ রক্ষক ও তত্ত্বাবধায়ক, যিনি সবকিছুর উপর নজর রাখেন এবং সংরক্ষণ করেন। কুরআন সম্পর্কেও এ শব্দ এসেছে, কারণ কুরআন আগের কিতাবের সত্যের সাক্ষী ও রক্ষক।", lessonBn: "আল্লাহ সবকিছু দেখছেন, এ চেতনা গোপন পাপ থেকে বাঁচতে সাহায্য করে।", quran: [{"ref": "সূরা আল-হাশর ৫৯:২৩", "ayat": ["59:23"], "gistBn": "তিনি ‘আল-মুহাইমিন’।"}], hadith: [] },
  { n: 8, ar: "الْعَزِيزُ", tr: "Al-ʿAzīz", bn: "আল-আযীয", en: "The Almighty", meaningBn: "মহাপরাক্রমশালী", detailBn: "‘আযীয’ অর্থ এমন পরাক্রমশালী যাঁকে পরাজিত করা যায় না। প্রকৃত সম্মান ও ক্ষমতা তাঁরই। কুরআনে প্রায়ই ‘আযীযুন হাকীম’ (পরাক্রমশালী ও প্রজ্ঞাময়) একসাথে এসেছে।", lessonBn: "সম্মান চাইলে আল্লাহর আনুগত্যের মধ্যেই তা খুঁজুন।", quran: [{"ref": "সূরা ফাতির ৩৫:১০", "ayat": ["35:10"], "gistBn": "যে সম্মান চায়, (সে জেনে রাখুক) সব সম্মান আল্লাহরই।"}], hadith: [] },
  { n: 9, ar: "الْجَبَّارُ", tr: "Al-Jabbār", bn: "আল-জাব্বার", en: "The Compeller", meaningBn: "মহাপ্রতাপশালী", detailBn: "‘জাব্বার’ অর্থ মহাপ্রতাপশালী, যিনি নিজের ইচ্ছা পূর্ণ করেন। আরেক অর্থে তিনি ভগ্নহৃদয় ও দুর্বলদের ক্ষত জোড়া দেন। আল্লাহর জন্য এ নাম প্রশংসনীয়, মানুষের জন্য ‘জাব্বার’ হওয়া নিন্দনীয়।", lessonBn: "ভেঙে পড়লে আল্লাহর কাছে চান; তিনিই ভাঙা মন জোড়া দেন।", quran: [{"ref": "সূরা আল-হাশর ৫৯:২৩", "ayat": ["59:23"], "gistBn": "তিনি ‘আল-জাব্বার’, ‘আল-মুতাকাব্বির’।"}], hadith: [] },
  { n: 10, ar: "الْمُتَكَبِّرُ", tr: "Al-Mutakabbir", bn: "আল-মুতাকাব্বির", en: "The Supreme in Greatness", meaningBn: "মহান গৌরবের অধিকারী", detailBn: "‘মুতাকাব্বির’ অর্থ সর্বোচ্চ বড়ত্বের অধিকারী। মানুষের জন্য অহংকার দোষের, কারণ সে সৃষ্ট ও সীমিত; আল্লাহর জন্য বড়ত্ব তাঁর প্রকৃত গুণ।", lessonBn: "অহংকার ত্যাগ করুন; বড়ত্ব কেবল আল্লাহর।", quran: [{"ref": "সূরা আল-হাশর ৫৯:২৩", "ayat": ["59:23"], "gistBn": "তিনি ‘আল-মুতাকাব্বির’।"}], hadith: [{"src": "সহীহ মুসলিম ২৬২০", "textBn": "আল্লাহ বলেন, বড়ত্ব আমার চাদর এবং মহিমা আমার লুঙ্গি। যে এ দুটির কোনোটি নিয়ে আমার সাথে টানাটানি করবে, আমি তাকে শাস্তি দেব।"}] },
  { n: 11, ar: "الْخَالِقُ", tr: "Al-Khāliq", bn: "আল-খালিক", en: "The Creator", meaningBn: "সৃষ্টিকর্তা", detailBn: "‘খালিক’ অর্থ সৃষ্টিকর্তা, যিনি আগের কোনো নমুনা ছাড়াই পরিমাপ ও পরিকল্পনা করে সৃষ্টি করেন। আসমান, জমিন, মানুষসহ সবকিছুর স্রষ্টা তিনিই।", lessonBn: "সৃষ্টির সৌন্দর্য দেখে স্রষ্টার প্রশংসা করুন।", quran: [{"ref": "সূরা আর-রা’দ ১৩:১৬", "ayat": ["13:16"], "gistBn": "আল্লাহ সবকিছুর স্রষ্টা।"}, {"ref": "সূরা আল-হাশর ৫৯:২৪", "ayat": ["59:24"], "gistBn": "তিনি ‘আল-খালিক, আল-বারি, আল-মুসাওয়ির’।"}], hadith: [] },
  { n: 12, ar: "الْبَارِئُ", tr: "Al-Bāriʾ", bn: "আল-বারি", en: "The Evolver", meaningBn: "উদ্ভাবক", detailBn: "‘বারি’ অর্থ যিনি সৃষ্টিকে অস্তিত্ব দেন এবং ত্রুটিহীনভাবে গড়ে তোলেন। ‘খালিক’ হলো পরিকল্পনা, ‘বারি’ হলো তা বাস্তবে রূপ দেওয়া।", lessonBn: "আল্লাহ যেভাবে আপনাকে সৃষ্টি করেছেন তার জন্য কৃতজ্ঞ থাকুন।", quran: [{"ref": "সূরা আল-হাশর ৫৯:২৪", "ayat": ["59:24"], "gistBn": "তিনি ‘আল-খালিক, আল-বারি, আল-মুসাওয়ির’।"}], hadith: [] },
  { n: 13, ar: "الْمُصَوِّرُ", tr: "Al-Muṣawwir", bn: "আল-মুসাওয়ির", en: "The Fashioner", meaningBn: "রূপদাতা", detailBn: "‘মুসাওয়ির’ অর্থ আকৃতিদাতা। তিনি প্রতিটি সৃষ্টিকে আলাদা রূপ ও চেহারা দেন। এজন্যই কোটি মানুষের মধ্যেও চেহারা ও আঙুলের ছাপ আলাদা।", lessonBn: "নিজের শারীরিক গড়ন নিয়ে হীনমন্য না হয়ে শুকরিয়া আদায় করুন।", quran: [{"ref": "সূরা গাফির ৪০:৬৪", "ayat": ["40:64"], "gistBn": "তিনি তোমাদের আকৃতি দিয়েছেন এবং তোমাদের আকৃতি সুন্দর করেছেন।"}, {"ref": "সূরা আল-ইনফিতার ৮২:৭-৮", "ayat": ["82:7", "82:8"], "gistBn": "তিনি তোমাকে সুবিন্যস্ত করেছেন এবং যে আকৃতিতে চেয়েছেন গঠন করেছেন।"}], hadith: [] },
  { n: 14, ar: "الْغَفَّارُ", tr: "Al-Ghaffār", bn: "আল-গাফফার", en: "The Constant Forgiver", meaningBn: "বারবার ক্ষমাকারী", detailBn: "‘গাফফার’ অর্থ বারবার ও অধিক ক্ষমাকারী। বান্দা যতবারই গুনাহ করে ফিরে আসুক, তিনি ক্ষমা করেন, যদি সে আন্তরিকভাবে তওবা করে। নূহ (আ.) নিজ কওমকে এ নামের ভরসা দিয়েই ইস্তিগফারের দাওয়াত দিয়েছিলেন।", lessonBn: "গুনাহ করে হতাশ হবেন না; দ্রুত তওবা ও ইস্তিগফার করুন।", quran: [{"ref": "সূরা নূহ ৭১:১০", "ayat": ["71:10"], "gistBn": "তোমরা তোমাদের রবের কাছে ক্ষমা চাও, নিশ্চয়ই তিনি ‘গাফফার’।"}, {"ref": "সূরা আয-যুমার ৩৯:৫৩", "ayat": ["39:53"], "gistBn": "আল্লাহর রহমত থেকে নিরাশ হয়ো না; তিনি সব গুনাহ ক্ষমা করেন।"}], hadith: [{"src": "সহীহ মুসলিম ২৭৪৯", "textBn": "নবী ﷺ বলেন, তোমরা যদি গুনাহই না করতে, আল্লাহ তোমাদের সরিয়ে এমন জাতি আনতেন যারা গুনাহ করে ক্ষমা চাইত, আর তিনি তাদের ক্ষমা করতেন।"}] },
  { n: 15, ar: "الْقَهَّارُ", tr: "Al-Qahhār", bn: "আল-কাহহার", en: "The All-Subduer", meaningBn: "মহাপ্রতাপে সবকিছু বশকারী", detailBn: "‘কাহহার’ অর্থ সবকিছুর উপর পূর্ণ আধিপত্য ও বিজয়ের অধিকারী। সব সৃষ্টি তাঁর ইচ্ছার কাছে বাধ্য। কিয়ামতের দিন ঘোষণা হবে, আজ রাজত্ব কার? উত্তর: এক ও মহাপরাক্রমশালী আল্লাহর।", lessonBn: "জালিমের ক্ষমতা দেখে ভয় পাবেন না; সবার উপরে আল্লাহর ক্ষমতা।", quran: [{"ref": "সূরা গাফির ৪০:১৬", "ayat": ["40:16"], "gistBn": "আজ রাজত্ব কার? এক ও মহাপরাক্রমশালী (আল-ওয়াহিদিল কাহহার) আল্লাহর।"}, {"ref": "সূরা আর-রা’দ ১৩:১৬", "ayat": ["13:16"], "gistBn": "বলো, তিনি এক ও মহাপরাক্রমশালী।"}], hadith: [] },
  { n: 16, ar: "الْوَهَّابُ", tr: "Al-Wahhāb", bn: "আল-ওয়াহহাব", en: "The Bestower", meaningBn: "মহাদানশীল", detailBn: "‘ওয়াহহাব’ অর্থ বিনিময় ছাড়া অবিরত দানকারী। তিনি চাওয়ার আগেও দান করেন। নবীরা এ নামের উসিলায় দুআ করেছেন। সুলাইমান (আ.) অনন্য রাজত্বের জন্য দুআ করেছিলেন।", lessonBn: "দুআয় ‘ইন্নাকা আনতাল ওয়াহহাব’ বলে চাওয়ার অভ্যাস করুন।", quran: [{"ref": "সূরা আলে ইমরান ৩:৮", "ayat": ["3:8"], "gistBn": "হে আমাদের রব! হিদায়াতের পর আমাদের অন্তর বক্র করবেন না; আপনার কাছ থেকে রহমত দিন, নিশ্চয়ই আপনি ‘আল-ওয়াহহাব’।"}, {"ref": "সূরা সোয়াদ ৩৮:৩৫", "ayat": ["38:35"], "gistBn": "সুলাইমান (আ.)-এর দুআ।"}], hadith: [{"src": "সূরা সোয়াদ ৩৮:৩৫", "textBn": "সুলাইমান (আ.) দুআ করেছিলেন, ‘হে আমার রব! আমাকে ক্ষমা করুন এবং এমন রাজত্ব দিন যা আমার পর আর কারো জন্য শোভন হবে না; নিশ্চয়ই আপনি মহাদাতা।’"}] },
  { n: 17, ar: "الرَّزَّاقُ", tr: "Ar-Razzāq", bn: "আর-রাযযাক", en: "The Provider", meaningBn: "রিযিকদাতা", detailBn: "‘রাযযাক’ অর্থ সব সৃষ্টির রিযিকদাতা। মানুষ শুধু মাধ্যম, প্রকৃত রিযিকদাতা আল্লাহ। মাটির প্রতিটি প্রাণীর রিযিকের দায়িত্ব তাঁরই।", lessonBn: "হালাল উপায়ে চেষ্টা করুন এবং রিযিকের জন্য আল্লাহর উপর ভরসা রাখুন।", quran: [{"ref": "সূরা হুদ ১১:৬", "ayat": ["11:6"], "gistBn": "জমিনে বিচরণকারী প্রতিটি প্রাণীর রিযিক আল্লাহর দায়িত্বে।"}, {"ref": "সূরা আয-যারিয়াত ৫১:৫৮", "ayat": ["51:58"], "gistBn": "নিশ্চয়ই আল্লাহই রিযিকদাতা, প্রবল শক্তির অধিকারী।"}], hadith: [{"src": "জামে তিরমিযি ২৩৪৪", "textBn": "নবী ﷺ বলেন, তোমরা যদি যথাযথভাবে আল্লাহর উপর ভরসা করতে, তিনি তোমাদের পাখির মতো রিযিক দিতেন; সকালে খালি পেটে বের হয় আর সন্ধ্যায় ভরা পেটে ফেরে।"}] },
  { n: 18, ar: "الْفَتَّاحُ", tr: "Al-Fattāḥ", bn: "আল-ফাত্তাহ", en: "The Opener", meaningBn: "উন্মোচনকারী", detailBn: "‘ফাত্তাহ’ অর্থ উন্মোচনকারী। তিনি রহমত, রিযিক ও সফলতার বন্ধ দরজা খুলে দেন এবং সত্য-মিথ্যার মধ্যে চূড়ান্ত ফয়সালা করেন।", lessonBn: "কঠিন সময়ে বলুন, ‘হে ফাত্তাহ! আমার জন্য সহজ করে দিন’।", quran: [{"ref": "সূরা সাবা ৩৪:২৬", "ayat": ["34:26"], "gistBn": "বলো, আমাদের রব আমাদের একত্র করবেন, অতঃপর ন্যায্যভাবে আমাদের মধ্যে ফয়সালা করবেন; তিনি ‘আল-ফাত্তাহ আল-আলীম’।"}, {"ref": "সূরা ফাতির ৩৫:২", "ayat": ["35:2"], "gistBn": "আল্লাহ মানুষের জন্য রহমতের যে দরজা খুলে দেন, কেউ তা আটকাতে পারে না।"}], hadith: [] },
  { n: 19, ar: "الْعَلِيمُ", tr: "Al-ʿAlīm", bn: "আল-আলীম", en: "The All-Knowing", meaningBn: "সর্বজ্ঞ", detailBn: "‘আলীম’ অর্থ সর্বজ্ঞ। প্রকাশ্য-গোপন, অতীত-ভবিষ্যৎ, মনের ভেতরের কথা সবই তিনি জানেন। অদৃশ্যের চাবিকাঠি একমাত্র তাঁর কাছে।", lessonBn: "মনের গোপন বিষয়ও আল্লাহ জানেন; তাই নিয়ত শুদ্ধ রাখুন।", quran: [{"ref": "সূরা আল-বাকারা ২:২৯", "ayat": ["2:29"], "gistBn": "তিনি সবকিছু সম্পর্কে সম্যক অবগত।"}, {"ref": "সূরা আল-আনআম ৬:৫৯", "ayat": ["6:59"], "gistBn": "অদৃশ্যের চাবিকাঠি তাঁরই কাছে, তিনি ছাড়া কেউ তা জানে না।"}], hadith: [] },
  { n: 20, ar: "الْقَابِضُ", tr: "Al-Qābiḍ", bn: "আল-কাবিদ", en: "The Withholder", meaningBn: "সংকুচিতকারী", detailBn: "‘কাবিদ’ অর্থ সংকুচিতকারী। আল্লাহ হিকমত অনুযায়ী যার জন্য ইচ্ছা রিযিক বা প্রাণ সংকুচিত করেন। অভাব বা কষ্ট অনেক সময় পরীক্ষা বা কল্যাণের কারণ হয়।", lessonBn: "সংকীর্ণতায় ধৈর্য ধরুন; এটি আল্লাহর হিকমতের অংশ।", quran: [{"ref": "সূরা আল-বাকারা ২:২৪৫", "ayat": ["2:245"], "gistBn": "আল্লাহই সংকুচিত করেন ও প্রসারিত করেন।"}], hadith: [{"src": "সুনানে আবু দাউদ ৩৪৫১, জামে তিরমিযি ১৩১৪", "textBn": "নবী ﷺ বলেন, নিশ্চয়ই আল্লাহই মূল্য নির্ধারণকারী, সংকুচিতকারী, প্রসারিতকারী ও রিযিকদাতা।"}] },
  { n: 21, ar: "الْبَاسِطُ", tr: "Al-Bāsiṭ", bn: "আল-বাসিত", en: "The Expander", meaningBn: "প্রসারিতকারী", detailBn: "‘বাসিত’ অর্থ প্রসারিতকারী। তিনি যার জন্য ইচ্ছা রিযিক, জ্ঞান ও রহমত প্রশস্ত করে দেন। কাবিদ ও বাসিত একসাথে স্মরণ করলে বোঝা যায়, সচ্ছলতা ও অভাব দুটোই তাঁর হাতে।", lessonBn: "সচ্ছলতায় অহংকার নয়, শুকরিয়া করুন।", quran: [{"ref": "সূরা আর-রা’দ ১৩:২৬", "ayat": ["13:26"], "gistBn": "আল্লাহ যার জন্য ইচ্ছা রিযিক প্রসারিত করেন ও সংকুচিত করেন।"}], hadith: [] },
  { n: 22, ar: "الْخَافِضُ", tr: "Al-Khāfiḍ", bn: "আল-খাফিদ", en: "The Abaser", meaningBn: "অবনতকারী", detailBn: "‘খাফিদ’ অর্থ অবনতকারী। যারা অহংকার ও অবাধ্যতা করে, আল্লাহ তাদের মর্যাদা নামিয়ে দেন। কিয়ামতের দিন অনেকেই অবনত হবে, আবার অনেকে উন্নীত হবে।", lessonBn: "নিজেকে বড় ভাবলে আল্লাহ নামিয়ে দিতে পারেন, তাই বিনয়ী থাকুন।", quran: [{"ref": "সূরা আল-ওয়াকিআ ৫৬:৩", "ayat": ["56:3"], "gistBn": "তা (কিয়ামত) কাউকে অবনত করবে, কাউকে উন্নত করবে।"}], hadith: [] },
  { n: 23, ar: "الرَّافِعُ", tr: "Ar-Rāfiʿ", bn: "আর-রাফি", en: "The Exalter", meaningBn: "উন্নতকারী", detailBn: "‘রাফি’ অর্থ উন্নতকারী। ঈমান ও ইলমের কারণে আল্লাহ বান্দার মর্যাদা বাড়িয়ে দেন। নবী ইদরীস (আ.)-কে তিনি উচ্চ স্থানে উঠিয়েছেন।", lessonBn: "ঈমান ও ইলমের পথে চলুন; মর্যাদা আল্লাহই দেন।", quran: [{"ref": "সূরা আল-মুজাদালা ৫৮:১১", "ayat": ["58:11"], "gistBn": "আল্লাহ তোমাদের মধ্যে যারা ঈমান এনেছে এবং যাদের জ্ঞান দেওয়া হয়েছে তাদের মর্যাদা উঁচু করবেন।"}], hadith: [] },
  { n: 24, ar: "الْمُعِزُّ", tr: "Al-Muʿizz", bn: "আল-মুইজ্জ", en: "The Giver of Honor", meaningBn: "সম্মানদাতা", detailBn: "‘মুইজ্জ’ অর্থ যিনি সম্মান দান করেন। প্রকৃত ইজ্জত দুনিয়ার পদ বা সম্পদে নয়, আল্লাহর আনুগত্যে। সম্মান তাঁর হাতে, তিনি যাকে ইচ্ছা সম্মানিত করেন।", lessonBn: "সম্মানের জন্য মানুষের কাছে নত না হয়ে আল্লাহর কাছে চান।", quran: [{"ref": "সূরা আলে ইমরান ৩:২৬", "ayat": ["3:26"], "gistBn": "আপনি যাকে ইচ্ছা সম্মান দেন এবং যাকে ইচ্ছা অপমান করেন।"}], hadith: [] },
  { n: 25, ar: "الْمُذِلُّ", tr: "Al-Mudhill", bn: "আল-মুযিল্ল", en: "The Giver of Dishonor", meaningBn: "অপমানকারী", detailBn: "‘মুযিল্ল’ অর্থ যিনি অপদস্থ করেন। অহংকারী, জালিম ও অবাধ্যদের তিনি লাঞ্ছিত করেন। সম্মান ও অপমান দুটোই তাঁর হিকমতপূর্ণ ফয়সালা।", lessonBn: "আল্লাহর অবাধ্যতার লাঞ্ছনা থেকে তাঁর কাছে আশ্রয় চান।", quran: [{"ref": "সূরা আলে ইমরান ৩:২৬", "ayat": ["3:26"], "gistBn": "আপনি যাকে ইচ্ছা সম্মান দেন এবং যাকে ইচ্ছা অপমান করেন।"}], hadith: [] },
  { n: 26, ar: "السَّمِيعُ", tr: "As-Samīʿ", bn: "আস-সামী", en: "The All-Hearing", meaningBn: "সর্বশ্রোতা", detailBn: "‘সামী’ অর্থ সর্বশ্রোতা। উচ্চস্বর, ফিসফিস, মনের কথা, সব তিনি শোনেন। বান্দার দুআও তিনি শোনেন এবং কবুল করেন।", lessonBn: "আল্লাহ শুনছেন জেনে আস্থার সাথে দুআ করুন।", quran: [{"ref": "সূরা আশ-শূরা ৪২:১১", "ayat": ["42:11"], "gistBn": "তাঁর মতো কিছুই নেই; তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।"}, {"ref": "সূরা আল-মুজাদালা ৫৮:১", "ayat": ["58:1"], "gistBn": "আল্লাহ সেই নারীর কথা শুনেছেন, যে তার স্বামীর বিষয়ে আপনার সাথে তর্ক করছিল।"}], hadith: [{"src": "সহীহ বুখারি ২৯৯২, সহীহ মুসলিম ২৭০৪", "textBn": "নবী ﷺ বললেন, হে মানুষ! নিজেদের প্রতি নম্র হও। তোমরা তো বধির বা অনুপস্থিত কাউকে ডাকছ না; তোমরা ডাকছ সর্বশ্রোতা, অতি নিকটবর্তীকে।"}], story: { title: "খাওলা বিনতে সা’লাবা (রা.)", textBn: "খাওলা (রা.) তাঁর স্বামীর যিহারের বিষয়ে নবী ﷺ-এর কাছে অভিযোগ ও আল্লাহর কাছে ফরিয়াদ করছিলেন। আল্লাহ সূরা আল-মুজাদালার প্রথম আয়াত নাযিল করে তাঁর কথা শোনার কথা জানিয়ে দিলেন এবং সমাধান দিলেন।" } },
  { n: 27, ar: "الْبَصِيرُ", tr: "Al-Baṣīr", bn: "আল-বাসীর", en: "The All-Seeing", meaningBn: "সর্বদ্রষ্টা", detailBn: "‘বাসীর’ অর্থ সর্বদ্রষ্টা। ক্ষুদ্রতম বিষয়ও তাঁর দৃষ্টির বাইরে নয়। তিনি বান্দার প্রকাশ্য ও গোপন সব আমল দেখেন।", lessonBn: "একাকী থাকলেও আল্লাহ দেখছেন, এ কথা স্মরণ করুন।", quran: [{"ref": "সূরা আশ-শূরা ৪২:১১", "ayat": ["42:11"], "gistBn": "তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।"}, {"ref": "সূরা আল-মুলক ৬৭:১৯", "ayat": ["67:19"], "gistBn": "তিনি সবকিছুর দ্রষ্টা।"}], hadith: [{"src": "সহীহ মুসলিম ৮", "textBn": "ইহসানের সংজ্ঞায় নবী ﷺ বলেন, তুমি এমনভাবে আল্লাহর ইবাদত করবে যেন তুমি তাঁকে দেখছ; আর যদি তুমি তাঁকে না-ও দেখো, তিনি তো তোমাকে দেখছেন।"}] },
  { n: 28, ar: "الْحَكَمُ", tr: "Al-Ḥakam", bn: "আল-হাকাম", en: "The Judge", meaningBn: "চূড়ান্ত বিচারক", detailBn: "‘হাকাম’ অর্থ চূড়ান্ত বিচারক। তাঁর ফয়সালা সর্বশেষ ও সঠিক, কেউ তা পরিবর্তন করতে পারে না। কিয়ামতে তিনিই সবার মাঝে ফয়সালা করবেন।", lessonBn: "বিবাদে ধৈর্য ধরুন এবং ন্যায়ের পক্ষে থাকুন; আল্লাহই চূড়ান্ত বিচারক।", quran: [{"ref": "সূরা আল-আনআম ৬:১১৪", "ayat": ["6:114"], "gistBn": "আমি কি আল্লাহ ছাড়া অন্য কাউকে বিচারক খুঁজব?"}], hadith: [{"src": "সুনানে আবু দাউদ ৪৯৫৫", "textBn": "নবী ﷺ বলেন, আল্লাহই হাকাম এবং হুকুম বা ফয়সালা তাঁরই।"}] },
  { n: 29, ar: "الْعَدْلُ", tr: "Al-ʿAdl", bn: "আল-আদল", en: "The Utterly Just", meaningBn: "পরম ন্যায়বিচারক", detailBn: "‘আদল’ অর্থ পরম ন্যায়। তিনি কারো প্রতি সামান্যতম জুলুম করেন না; তিনি নিজের উপর জুলুমকে হারাম করেছেন। আখিরাতে প্রতিটি বিষয়ে পূর্ণ ইনসাফ হবে।", lessonBn: "নিজের ও অন্যের সাথে ন্যায়ের আচরণ করুন।", quran: [{"ref": "সূরা আন-নাহল ১৬:৯০", "ayat": ["16:90"], "gistBn": "আল্লাহ ন্যায়বিচার, সদাচরণ ও আত্মীয়দের দান করার নির্দেশ দেন।"}, {"ref": "সূরা আন-নিসা ৪:৪০", "ayat": ["4:40"], "gistBn": "আল্লাহ অণু পরিমাণও জুলুম করেন না।"}], hadith: [{"src": "সহীহ মুসলিম ২৫৭৭", "textBn": "আল্লাহ বলেন, হে আমার বান্দারা! আমি নিজের উপর জুলুম হারাম করেছি এবং তোমাদের মধ্যেও তা হারাম করেছি; তাই তোমরা একে অপরের উপর জুলুম করো না।"}] },
  { n: 30, ar: "اللَّطِيفُ", tr: "Al-Laṭīf", bn: "আল-লাতীফ", en: "The Subtle, The Kind", meaningBn: "সূক্ষ্মদর্শী ও সদয়", detailBn: "‘লাতীফ’ অর্থ সূক্ষ্মদর্শী ও সদয়। তিনি সূক্ষ্মতম বিষয়ও জানেন এবং এমন সূক্ষ্ম উপায়ে বান্দার জন্য কল্যাণ আনেন, যা বান্দা টেরও পায় না।", lessonBn: "কঠিন পরিস্থিতিতেও আল্লাহর সূক্ষ্ম পরিকল্পনার উপর ভরসা রাখুন।", quran: [{"ref": "সূরা আল-আনআম ৬:১০৩", "ayat": ["6:103"], "gistBn": "দৃষ্টি তাঁকে ধরতে পারে না, কিন্তু তিনি দৃষ্টিকে ধরতে পারেন; তিনি ‘আল-লাতীফ আল-খাবীর’।"}, {"ref": "সূরা ইউসুফ ১২:১০০", "ayat": ["12:100"], "gistBn": "আমার রব যা চান তা সূক্ষ্ম কৌশলে সম্পন্ন করেন।"}], hadith: [], story: { title: "ইউসুফ (আ.)", textBn: "ইউসুফ (আ.)-কে কূপে ফেলা, দাসত্ব ও কারাগারের কষ্ট পেরিয়ে আল্লাহ মিশরের ক্ষমতায় পৌঁছে দেন এবং পরিবারকে মিলিয়ে দেন। শেষে ইউসুফ (আ.) বলেন, আমার রব যা চান সূক্ষ্ম কৌশলে করেন।" } },
  { n: 31, ar: "الْخَبِيرُ", tr: "Al-Khabīr", bn: "আল-খাবীর", en: "The All-Aware", meaningBn: "সর্বাধিক অবহিত", detailBn: "‘খাবীর’ অর্থ সর্বাধিক অবহিত। বান্দার ভেতরের অবস্থা, নিয়ত ও গোপন বিষয় সম্পর্কে তিনি পুরোপুরি জানেন। ‘আলীম’ জ্ঞানের ব্যাপকতা, ‘খাবীর’ তার গভীরতা বোঝায়।", lessonBn: "কাজের বাহ্যিক রূপের চেয়ে নিয়ত ও অন্তর ঠিক রাখার চেষ্টা করুন।", quran: [{"ref": "সূরা আল-মুলক ৬৭:১৪", "ayat": ["67:14"], "gistBn": "যিনি সৃষ্টি করেছেন তিনি কি জানবেন না? তিনি সূক্ষ্মদর্শী, সম্যক অবহিত।"}, {"ref": "সূরা আল-আনআম ৬:১৮", "ayat": ["6:18"], "gistBn": "তিনি প্রজ্ঞাময়, সম্যক অবহিত।"}], hadith: [] },
  { n: 32, ar: "الْحَلِيمُ", tr: "Al-Ḥalīm", bn: "আল-হালীম", en: "The Forbearing", meaningBn: "পরম সহনশীল", detailBn: "‘হালীম’ অর্থ পরম সহনশীল। তিনি অবাধ্যদের সাথে সাথে শাস্তি দেন না, বরং সময় ও তওবার সুযোগ দেন। সহনশীলতা মানে দুর্বলতা নয়, ক্ষমতা থাকা সত্ত্বেও তাড়াহুড়া না করা।", lessonBn: "রাগের সময় আল্লাহর সহনশীলতা স্মরণ করে নিজেকে সংযত করুন।", quran: [{"ref": "সূরা আত-তাগাবুন ৬৪:১৭", "ayat": ["64:17"], "gistBn": "আল্লাহ গুণগ্রাহী, সহনশীল।"}], hadith: [{"src": "সহীহ বুখারি ৬৩৪৫, সহীহ মুসলিম ২৭৩০", "textBn": "বিপদের সময় নবী ﷺ বলতেন, ‘লা ইলাহা ইল্লাল্লাহুল আযীমুল হালীম’।"}] },
  { n: 33, ar: "الْعَظِيمُ", tr: "Al-ʿAẓīm", bn: "আল-আযীম", en: "The Magnificent", meaningBn: "মহিমান্বিত, মহান", detailBn: "‘আযীম’ অর্থ অসীম মহিমান্বিত। তাঁর সত্তা, গুণ ও কাজ মানুষের কল্পনার ঊর্ধ্বে। এ কারণে রুকুতে ‘সুবহানা রব্বিয়াল আযীম’ বলা হয়।", lessonBn: "বিপদ যত বড় হোক, আল্লাহ তার চেয়ে অনেক বড়।", quran: [{"ref": "সূরা আল-ওয়াকিআ ৫৬:৭৪", "ayat": ["56:74"], "gistBn": "অতএব তুমি তোমার মহান রবের নামে তাসবিহ পাঠ করো।"}], hadith: [{"src": "সহীহ বুখারি ৬৪০৬, সহীহ মুসলিম ২৬৯৪", "textBn": "নবী ﷺ বলেন, দুটি বাক্য যা মুখে সহজ, দাঁড়িপাল্লায় ভারী এবং দয়াময়ের কাছে প্রিয়: ‘সুবহানাল্লাহি ওয়া বিহামদিহী, সুবহানাল্লাহিল আযীম’।"}] },
  { n: 34, ar: "الْغَفُورُ", tr: "Al-Ghafūr", bn: "আল-গাফূর", en: "The Forgiving", meaningBn: "পরম ক্ষমাশীল", detailBn: "‘গাফূর’ অর্থ পরম ক্ষমাশীল। বান্দার গুনাহ ঢেকে রাখেন এবং শাস্তি থেকে মুক্তি দেন। কুরআনে ‘গাফূরুর রাহীম’ বহুবার এসেছে।", lessonBn: "গুনাহ গোপন রাখুন এবং আল্লাহর কাছে ক্ষমা চান।", quran: [{"ref": "সূরা আয-যুমার ৩৯:৫৩", "ayat": ["39:53"], "gistBn": "আল্লাহ সব গুনাহ ক্ষমা করেন; তিনিই ‘আল-গাফূরুর রাহীম’।"}], hadith: [] },
  { n: 35, ar: "الشَّكُورُ", tr: "Ash-Shakūr", bn: "আশ-শাকূর", en: "The Appreciative", meaningBn: "গুণগ্রাহী", detailBn: "‘শাকূর’ অর্থ গুণগ্রাহী। তিনি অল্প আমলেরও বহুগুণ প্রতিদান দেন এবং বান্দার কৃতজ্ঞতা কবুল করেন।", lessonBn: "ছোট আমলকেও হালকা ভাববেন না।", quran: [{"ref": "সূরা ফাতির ৩৫:৩০", "ayat": ["35:30"], "gistBn": "তিনি ক্ষমাশীল, গুণগ্রাহী।"}, {"ref": "সূরা আত-তাগাবুন ৬৪:১৭", "ayat": ["64:17"], "gistBn": "তোমরা আল্লাহকে উত্তম ঋণ দিলে তিনি তা বহুগুণ করে দেবেন, তিনি গুণগ্রাহী ও সহনশীল।"}], hadith: [] },
  { n: 36, ar: "الْعَلِيُّ", tr: "Al-ʿAliyy", bn: "আল-আলী", en: "The Most High", meaningBn: "সর্বোচ্চ", detailBn: "‘আলী’ অর্থ সর্বোচ্চ। সত্তা, ক্ষমতা ও মর্যাদা, সব দিক থেকে তিনি সবার উপরে। কেউ তাঁর সমকক্ষ বা তাঁর চেয়ে উঁচু নয়।", lessonBn: "কারো মর্যাদা দেখে প্রভাবিত না হয়ে আল্লাহর মহত্ত্ব স্মরণ করুন।", quran: [{"ref": "সূরা আল-বাকারা ২:২৫৫", "ayat": ["2:255"], "gistBn": "তিনি সর্বোচ্চ, সুমহান (‘আল-আলিয়্যুল আযীম’)।"}], hadith: [] },
  { n: 37, ar: "الْكَبِيرُ", tr: "Al-Kabīr", bn: "আল-কাবীর", en: "The Most Great", meaningBn: "সর্বমহান", detailBn: "‘কাবীর’ অর্থ সর্বমহান। ‘আল্লাহু আকবার’ বলার সময় আমরা এ গুণের স্বীকৃতিই দিই: আল্লাহ সবকিছুর চেয়ে বড়।", lessonBn: "প্রতিটি আযান ও নামাজে ‘আল্লাহু আকবার’ বলে এ স্বীকৃতি নবায়ন করুন।", quran: [{"ref": "সূরা আর-রা’দ ১৩:৯", "ayat": ["13:9"], "gistBn": "তিনি অদৃশ্য ও দৃশ্যের জ্ঞানী, মহান ও সর্বোচ্চ (‘আল-কাবীরুল মুতাআল’)।"}], hadith: [] },
  { n: 38, ar: "الْحَفِيظُ", tr: "Al-Ḥafīẓ", bn: "আল-হাফীয", en: "The Preserver", meaningBn: "মহান সংরক্ষক", detailBn: "‘হাফীয’ অর্থ মহান সংরক্ষক। তিনি আসমান-জমিন, বান্দার আমল ও জীবিকা সংরক্ষণ করেন। কুরআনও তাঁরই হিফাযতে।", lessonBn: "আল্লাহর আদেশ মানলে তিনি দুনিয়া ও আখিরাতে হিফাযত করেন।", quran: [{"ref": "সূরা ইউসুফ ১২:৬৪", "ayat": ["12:64"], "gistBn": "আল্লাহই সর্বোত্তম রক্ষক, তিনি সর্বশ্রেষ্ঠ দয়ালু।"}, {"ref": "সূরা আল-হিজর ১৫:৯", "ayat": ["15:9"], "gistBn": "আমিই কুরআন নাযিল করেছি এবং আমিই তার সংরক্ষক।"}], hadith: [{"src": "জামে তিরমিযি ২৫১৬", "textBn": "নবী ﷺ ইবনে আব্বাস (রা.)-কে বলেন, তুমি আল্লাহকে হিফাযত করো (তাঁর বিধান মানো), তিনি তোমাকে হিফাযত করবেন।"}] },
  { n: 39, ar: "الْمُقِيتُ", tr: "Al-Muqīt", bn: "আল-মুকীত", en: "The Sustainer", meaningBn: "জীবিকা ও শক্তিদাতা", detailBn: "‘মুকীত’ অর্থ জীবিকা ও শক্তিদাতা, অথবা সবকিছুর উপর সক্ষম ও তত্ত্বাবধায়ক। প্রতিটি প্রাণীর খাদ্য ও পুষ্টির ব্যবস্থা তাঁর কাছ থেকেই।", lessonBn: "খাবারের জন্য আল্লাহর শুকরিয়া আদায় করুন।", quran: [{"ref": "সূরা আন-নিসা ৪:৮৫", "ayat": ["4:85"], "gistBn": "আল্লাহ সবকিছুর উপর সক্ষম (‘মুকীত’)।"}], hadith: [] },
  { n: 40, ar: "الْحَسِيبُ", tr: "Al-Ḥasīb", bn: "আল-হাসীব", en: "The Reckoner", meaningBn: "হিসাবগ্রহণকারী ও যথেষ্ট", detailBn: "‘হাসীব’ অর্থ হিসাবগ্রহণকারী এবং বান্দার জন্য যথেষ্ট। তিনি প্রতিটি আমলের হিসাব রাখেন; আবার যে তাঁর উপর ভরসা করে, তার জন্য তিনিই যথেষ্ট।", lessonBn: "প্রতিদিন নিজের আমলের হিসাব নিন; আল্লাহর কাছে হিসাব দিতে হবে।", quran: [{"ref": "সূরা আন-নিসা ৪:৮৬", "ayat": ["4:86"], "gistBn": "নিশ্চয়ই আল্লাহ সবকিছুর হিসাবগ্রহণকারী।"}, {"ref": "সূরা আত-তালাক ৬৫:৩", "ayat": ["65:3"], "gistBn": "যে আল্লাহর উপর ভরসা করে, তার জন্য তিনিই যথেষ্ট।"}], hadith: [] },
  { n: 41, ar: "الْجَلِيلُ", tr: "Al-Jalīl", bn: "আল-জালীল", en: "The Majestic", meaningBn: "প্রতাপ ও মহিমার অধিকারী", detailBn: "‘জালীল’ অর্থ প্রতাপ ও মহিমার অধিকারী। তাঁর সত্তা ও গুণাবলি পরিপূর্ণ মর্যাদায় ভরপুর, যা সৃষ্টির কল্পনার বাইরে। ‘যুল জালাল’ (মহিমার অধিকারী) নামেও এ গুণ প্রকাশ পায়।", lessonBn: "আল্লাহর মহিমা স্মরণ করে তাঁর সামনে বিনয়ী হোন।", quran: [{"ref": "সূরা আর-রাহমান ৫৫:২৭", "ayat": ["55:27"], "gistBn": "আপনার রবের চেহারা অবশিষ্ট থাকবে, যিনি মহিমা ও সম্মানের অধিকারী।"}], hadith: [] },
  { n: 42, ar: "الْكَرِيمُ", tr: "Al-Karīm", bn: "আল-কারীম", en: "The Generous", meaningBn: "পরম দানশীল, মহানুভব", detailBn: "‘কারীম’ অর্থ পরম দানশীল ও মহানুভব। তিনি চাওয়ার আগেও দেন, প্রয়োজনের চেয়ে বেশি দেন এবং ক্ষমা করেন। তাঁর দান কখনো ফুরায় না।", lessonBn: "দুআ করতে লজ্জা বা সংকোচ করবেন না; আল্লাহ মহানুভব।", quran: [{"ref": "সূরা আন-নামল ২৭:৪০", "ayat": ["27:40"], "gistBn": "আমার রব অমুখাপেক্ষী, মহানুভব।"}, {"ref": "সূরা আল-ইনফিতার ৮২:৬", "ayat": ["82:6"], "gistBn": "হে মানুষ! কিসে তোমাকে তোমার মহানুভব রব সম্পর্কে ধোঁকায় ফেলল?"}], hadith: [{"src": "সুনানে আবু দাউদ ১৪৮৮, জামে তিরমিযি ৩৫৫৬", "textBn": "নবী ﷺ বলেন, তোমাদের রব লজ্জাশীল ও মহানুভব। বান্দা তাঁর দিকে হাত তুললে তিনি সেই হাত খালি ফিরিয়ে দিতে লজ্জা পান।"}] },
  { n: 43, ar: "الرَّقِيبُ", tr: "Ar-Raqīb", bn: "আর-রাকীব", en: "The Watchful", meaningBn: "সদা পর্যবেক্ষক", detailBn: "‘রাকীব’ অর্থ সদা পর্যবেক্ষক। তিনি বান্দার প্রতিটি কথা, কাজ ও মনের অবস্থার উপর সজাগ দৃষ্টি রাখেন। কিছুই তাঁর পর্যবেক্ষণের বাইরে নয়।", lessonBn: "নির্জনেও পাপ থেকে বাঁচুন; আল্লাহ সবসময় দেখছেন।", quran: [{"ref": "সূরা আন-নিসা ৪:১", "ayat": ["4:1"], "gistBn": "নিশ্চয়ই আল্লাহ তোমাদের উপর পর্যবেক্ষক।"}], hadith: [] },
  { n: 44, ar: "الْمُجِيبُ", tr: "Al-Mujīb", bn: "আল-মুজীব", en: "The Responsive", meaningBn: "দুআ কবুলকারী", detailBn: "‘মুজীব’ অর্থ যিনি সাড়া দেন। বান্দা ডাকলে তিনি শোনেন এবং নিজ হিকমত অনুযায়ী কবুল করেন। দুআর ক্ষেত্রে মাঝখানে কোনো মাধ্যমের প্রয়োজন নেই।", lessonBn: "সবসময় দুআ করুন; আল্লাহ সাড়া দেন, কখনো চাওয়া জিনিস দিয়ে, কখনো তার চেয়ে ভালো কিছু দিয়ে।", quran: [{"ref": "সূরা আল-বাকারা ২:১৮৬", "ayat": ["2:186"], "gistBn": "আমার বান্দারা আপনার কাছে আমার সম্পর্কে জিজ্ঞেস করলে বলুন, আমি অতি নিকটে; প্রার্থনাকারী ডাকলে আমি সাড়া দিই।"}, {"ref": "সূরা হুদ ১১:৬১", "ayat": ["11:61"], "gistBn": "নিশ্চয়ই আমার রব নিকটবর্তী, সাড়াদানকারী।"}], hadith: [], story: { title: "ইউনুস (আ.)", textBn: "ইউনুস (আ.) মাছের পেটের অন্ধকারে ডেকেছিলেন, ‘লা ইলাহা ইল্লা আনতা সুবহানাকা ইন্নী কুনতু মিনায যালিমীন’। আল্লাহ তাঁর ডাকে সাড়া দিয়ে তাঁকে দুশ্চিন্তা থেকে মুক্তি দিলেন। (সূরা আল-আম্বিয়া ২১:৮৭-৮৮)" } },
  { n: 45, ar: "الْوَاسِعُ", tr: "Al-Wāsiʿ", bn: "আল-ওয়াসি", en: "The All-Encompassing", meaningBn: "সর্বব্যাপী প্রাচুর্যশীল", detailBn: "‘ওয়াসি’ অর্থ সর্বব্যাপী প্রাচুর্যের অধিকারী। তাঁর জ্ঞান, রহমত, রিযিক ও ক্ষমতার কোনো সীমা নেই। যত চাওয়া হোক, তাঁর ভাণ্ডারে কমতি আসে না।", lessonBn: "আল্লাহর কাছে বড় কিছু চাইতে সংকোচ করবেন না।", quran: [{"ref": "সূরা আল-বাকারা ২:১১৫", "ayat": ["2:115"], "gistBn": "পূর্ব ও পশ্চিম আল্লাহরই; তোমরা যেদিকে মুখ ফেরাও সেদিকেই আল্লাহর চেহারা আছে; নিশ্চয়ই আল্লাহ সর্বব্যাপী, সর্বজ্ঞ।"}, {"ref": "সূরা আল-বাকারা ২:২৬১", "ayat": ["2:261"], "gistBn": "আল্লাহ যার জন্য ইচ্ছা বহুগুণ বাড়িয়ে দেন; আল্লাহ সর্বব্যাপী, সর্বজ্ঞ।"}], hadith: [] },
  { n: 46, ar: "الْحَكِيمُ", tr: "Al-Ḥakīm", bn: "আল-হাকীম", en: "The All-Wise", meaningBn: "প্রজ্ঞাময়", detailBn: "‘হাকীম’ অর্থ প্রজ্ঞাময়। তাঁর প্রতিটি আদেশ, নিষেধ, সৃষ্টি ও সিদ্ধান্ত গভীর হিকমতে পূর্ণ, যদিও আমরা সবসময় তা বুঝি না। কুরআনে ‘আযীযুন হাকীম’ ও ‘আলীমুন হাকীম’ একসাথে বহুবার এসেছে।", lessonBn: "কোনো ঘটনার কারণ না বুঝলেও আল্লাহর হিকমতের উপর আস্থা রাখুন।", quran: [{"ref": "সূরা আল-আনআম ৬:১৮", "ayat": ["6:18"], "gistBn": "তিনি তাঁর বান্দাদের উপর পরাক্রমশালী এবং তিনি প্রজ্ঞাময়, সম্যক অবহিত।"}, {"ref": "সূরা লুকমান ৩১:২৭", "ayat": ["31:27"], "gistBn": "নিশ্চয়ই আল্লাহ পরাক্রমশালী, প্রজ্ঞাময়।"}], hadith: [] },
  { n: 47, ar: "الْوَدُودُ", tr: "Al-Wadūd", bn: "আল-ওয়াদূদ", en: "The Most Loving", meaningBn: "অতি স্নেহময়", detailBn: "‘ওয়াদূদ’ অর্থ অতি স্নেহময় ও ভালোবাসাময়। তিনি তাঁর নেককার বান্দাদের ভালোবাসেন এবং তাদের জন্য মানুষের অন্তরেও ভালোবাসা সৃষ্টি করেন। তওবাকারীর প্রতিও তিনি স্নেহশীল।", lessonBn: "আল্লাহর ভালোবাসা পেতে নেক আমল ও তওবার পথে থাকুন।", quran: [{"ref": "সূরা আল-বুরূজ ৮৫:১৪", "ayat": ["85:14"], "gistBn": "তিনি ক্ষমাশীল, প্রেমময়।"}, {"ref": "সূরা হুদ ১১:৯০", "ayat": ["11:90"], "gistBn": "তোমাদের রবের কাছে ক্ষমা চাও ও তওবা করো; নিশ্চয়ই আমার রব পরম দয়ালু, প্রেমময়।"}], hadith: [{"src": "সহীহ বুখারি ৩২০৯, সহীহ মুসলিম ২৬৩৭", "textBn": "নবী ﷺ বলেন, আল্লাহ কোনো বান্দাকে ভালোবাসলে জিবরীলকে ডেকে বলেন, আমি অমুককে ভালোবাসি, তুমিও তাকে ভালোবাসো। তখন আসমানে ঘোষণা হয়, এরপর জমিনেও তার জন্য গ্রহণযোগ্যতা রাখা হয়।"}] },
  { n: 48, ar: "الْمَجِيدُ", tr: "Al-Majīd", bn: "আল-মাজীদ", en: "The Glorious", meaningBn: "মহিমান্বিত", detailBn: "‘মাজীদ’ অর্থ সম্মান ও মর্যাদায় অতি উচ্চ, গৌরবান্বিত। এ নামে মহিমা ও দানশীলতা দুটোই আছে। দরূদে ‘ইন্নাকা হামীদুম মাজীদ’ বলে আমরা এ গুণের স্বীকৃতি দিই।", lessonBn: "দরূদ পড়ার সময় ‘হামীদুম মাজীদ’-এর অর্থ মনে রাখুন।", quran: [{"ref": "সূরা আল-বুরূজ ৮৫:১৫", "ayat": ["85:15"], "gistBn": "আরশের অধিপতি, মহিমান্বিত।"}, {"ref": "সূরা হুদ ১১:৭৩", "ayat": ["11:73"], "gistBn": "নিশ্চয়ই তিনি প্রশংসিত, মহিমান্বিত।"}], hadith: [] },
  { n: 49, ar: "الْبَاعِثُ", tr: "Al-Bāʿith", bn: "আল-বায়িস", en: "The Resurrector", meaningBn: "পুনরুত্থানকারী", detailBn: "‘বায়িস’ অর্থ যিনি পুনরুত্থিত করবেন। কিয়ামতের দিন তিনি কবরে থাকা সবাইকে জীবিত করে হিসাবের জন্য উঠাবেন। এর প্রতি বিশ্বাস আখিরাতের উপর ঈমানের অংশ।", lessonBn: "আখিরাতে জবাবদিহির কথা স্মরণ করে জীবন গড়ুন।", quran: [{"ref": "সূরা আল-হাজ্জ ২২:৭", "ayat": ["22:7"], "gistBn": "কিয়ামত অবশ্যম্ভাবী, এতে সন্দেহ নেই; আর আল্লাহ কবরবাসীদের পুনরুত্থিত করবেন।"}], hadith: [] },
  { n: 50, ar: "الشَّهِيدُ", tr: "Ash-Shahīd", bn: "আশ-শাহীদ", en: "The Witness", meaningBn: "সর্বসাক্ষী", detailBn: "‘শাহীদ’ অর্থ সর্বসাক্ষী। সবকিছুর উপর তিনি প্রত্যক্ষ সাক্ষী; কোনো কাজ বা কথা তাঁর অগোচরে নেই। কিয়ামতে তিনি বান্দার আমলের সাক্ষ্য দেবেন।", lessonBn: "কোনো কাজ করার আগে ভাবুন, আল্লাহ এর সাক্ষী।", quran: [{"ref": "সূরা আল-হাজ্জ ২২:১৭", "ayat": ["22:17"], "gistBn": "নিশ্চয়ই আল্লাহ সবকিছুর সাক্ষী।"}, {"ref": "সূরা আল-মায়িদা ৫:১১৭", "ayat": ["5:117"], "gistBn": "আর আপনিই সবকিছুর উপর সাক্ষী।"}], hadith: [] },
  { n: 51, ar: "الْحَقُّ", tr: "Al-Ḥaqq", bn: "আল-হাক", en: "The Truth", meaningBn: "পরম সত্য", detailBn: "‘হাক’ অর্থ পরম সত্য। তাঁর অস্তিত্ব, তাঁর ওয়াদা ও তাঁর কিতাব চূড়ান্ত সত্য। আল্লাহ ছাড়া যাদের ডাকা হয়, সবই বাতিল।", lessonBn: "সত্যের পক্ষে থাকুন এবং মিথ্যার সাথে আপস করবেন না।", quran: [{"ref": "সূরা আল-হাজ্জ ২২:৬", "ayat": ["22:6"], "gistBn": "এটা এ কারণে যে আল্লাহই সত্য।"}, {"ref": "সূরা লুকমান ৩১:৩০", "ayat": ["31:30"], "gistBn": "এটা এ কারণে যে আল্লাহই সত্য এবং তাঁর পরিবর্তে যাদের ডাকে তারা বাতিল।"}], hadith: [] },
  { n: 52, ar: "الْوَكِيلُ", tr: "Al-Wakīl", bn: "আল-ওয়াকীল", en: "The Trustee", meaningBn: "কার্যনির্বাহী, ভরসাস্থল", detailBn: "‘ওয়াকীল’ অর্থ কার্যনির্বাহী ও ভরসাস্থল। বান্দা তাঁর উপর ভরসা করলে তিনি বান্দার সব বিষয় দায়িত্ব নিয়ে সামলান। তাওয়াক্কুল মানে চেষ্টা বাদ দেওয়া নয়, চেষ্টার পর ফল আল্লাহর উপর ছেড়ে দেওয়া।", lessonBn: "বিপদে বলুন, ‘হাসবুনাল্লাহু ওয়া নিমাল ওয়াকীল’।", quran: [{"ref": "সূরা আলে ইমরান ৩:১৭৩", "ayat": ["3:173"], "gistBn": "তারা বলল, আল্লাহই আমাদের জন্য যথেষ্ট এবং তিনি কত উত্তম কর্মবিধায়ক।"}], hadith: [{"src": "সহীহ বুখারি ৪৫৬৩", "textBn": "ইবনে আব্বাস (রা.) বলেন, ইবরাহীম (আ.)-কে আগুনে নিক্ষেপ করার সময় এবং লোকেরা মুসলিমদের বিরুদ্ধে জড়ো হয়েছে শুনে মুহাম্মাদ ﷺ এ কথাই বলেছিলেন: হাসবুনাল্লাহু ওয়া নিমাল ওয়াকীল।"}], story: { title: "ইবরাহীম (আ.) ও আগুন", textBn: "নমরূদের লোকেরা ইবরাহীম (আ.)-কে আগুনে ফেলেছিল। তিনি আল্লাহর উপর ভরসা করে বলেছিলেন, হাসবুনাল্লাহু ওয়া নিমাল ওয়াকীল। আল্লাহ আগুনকে ঠান্ডা ও নিরাপদ করে দিলেন। (সূরা আল-আম্বিয়া ২১:৬৯)" } },
  { n: 53, ar: "الْقَوِيُّ", tr: "Al-Qawiyy", bn: "আল-কাবী", en: "The All-Strong", meaningBn: "মহাশক্তিমান", detailBn: "‘কাবী’ অর্থ মহাশক্তিমান। তাঁর শক্তি কখনো কমে না, তিনি কখনো ক্লান্ত বা দুর্বল হন না। সব শক্তি তাঁরই দান।", lessonBn: "নিজের দুর্বলতার সময় আল্লাহর শক্তির কাছে আশ্রয় চান।", quran: [{"ref": "সূরা আয-যারিয়াত ৫১:৫৮", "ayat": ["51:58"], "gistBn": "নিশ্চয়ই আল্লাহই রিযিকদাতা, প্রবল শক্তির অধিকারী, সুদৃঢ়।"}], hadith: [] },
  { n: 54, ar: "الْمَتِينُ", tr: "Al-Matīn", bn: "আল-মাতীন", en: "The Firm", meaningBn: "সুদৃঢ়", detailBn: "‘মাতীন’ অর্থ সুদৃঢ় ও অটল। তাঁর শক্তি এমন দৃঢ় যে কেউ তা ভাঙতে বা টলাতে পারে না। ‘কাবী’ শক্তির অস্তিত্ব বোঝায়, ‘মাতীন’ তার স্থিতিশীলতা ও অপরাজেয়তা বোঝায়।", lessonBn: "ঈমানে দৃঢ় থাকুন; আল্লাহ দৃঢ়পদদের সাহায্য করেন।", quran: [{"ref": "সূরা আয-যারিয়াত ৫১:৫৮", "ayat": ["51:58"], "gistBn": "নিশ্চয়ই আল্লাহই রিযিকদাতা, প্রবল শক্তির অধিকারী, সুদৃঢ়।"}], hadith: [] },
  { n: 55, ar: "الْوَلِيُّ", tr: "Al-Waliyy", bn: "আল-ওয়ালী", en: "The Protecting Friend", meaningBn: "অভিভাবক ও বন্ধু", detailBn: "‘ওয়ালী’ অর্থ অভিভাবক ও বন্ধু। তিনি ঈমানদারদের সাহায্যকারী ও তত্ত্বাবধায়ক। তিনি তাদের অন্ধকার থেকে আলোর দিকে নিয়ে যান।", lessonBn: "কারো সাহায্য না পেলেও মনে রাখুন, আল্লাহ আপনার ওয়ালী।", quran: [{"ref": "সূরা আল-বাকারা ২:২৫৭", "ayat": ["2:257"], "gistBn": "আল্লাহ মুমিনদের অভিভাবক; তিনি তাদের অন্ধকার থেকে আলোর দিকে বের করে আনেন।"}, {"ref": "সূরা আশ-শূরা ৪২:২৮", "ayat": ["42:28"], "gistBn": "তিনিই অভিভাবক, প্রশংসিত।"}], hadith: [] },
  { n: 56, ar: "الْحَمِيدُ", tr: "Al-Ḥamīd", bn: "আল-হামীদ", en: "The Praiseworthy", meaningBn: "প্রশংসিত", detailBn: "‘হামীদ’ অর্থ প্রশংসিত। তিনি নিজ সত্তা ও গুণে প্রশংসার যোগ্য, কেউ প্রশংসা করুক বা না করুক। আমরা ‘আলহামদুলিল্লাহ’ বলে এ গুণের স্বীকৃতি দিই।", lessonBn: "প্রতিটি নিয়ামতে ‘আলহামদুলিল্লাহ’ বলার অভ্যাস করুন।", quran: [{"ref": "সূরা আল-ফাতিহা ১:২", "ayat": ["1:2"], "gistBn": "সব প্রশংসা আল্লাহর, যিনি জগতসমূহের রব।"}, {"ref": "সূরা লুকমান ৩১:১২", "ayat": ["31:12"], "gistBn": "যে অকৃতজ্ঞ হয়, (সে জেনে রাখুক) নিশ্চয়ই আল্লাহ অমুখাপেক্ষী, প্রশংসিত।"}], hadith: [] },
  { n: 57, ar: "الْمُحْصِي", tr: "Al-Muḥṣī", bn: "আল-মুহসী", en: "The Reckoner", meaningBn: "পূর্ণ গণনাকারী", detailBn: "‘মুহসী’ অর্থ পূর্ণ গণনাকারী। আসমান-জমিনের প্রতিটি কণা, বৃষ্টির ফোঁটা ও বান্দার প্রতিটি আমল তাঁর হিসাবে আছে। কিছুই ছুটে যায় না।", lessonBn: "ছোট ভালো কাজও আল্লাহ গুনে রাখেন, তাই অবহেলা করবেন না।", quran: [{"ref": "সূরা মারইয়াম ১৯:৯৪", "ayat": ["19:94"], "gistBn": "তিনি তাদের গণনা করে রেখেছেন এবং পুরোপুরি গুনে রেখেছেন।"}, {"ref": "সূরা ইয়াসীন ৩৬:১২", "ayat": ["36:12"], "gistBn": "আমি প্রতিটি বিষয় স্পষ্ট কিতাবে গণনা করে রেখেছি।"}], hadith: [] },
  { n: 58, ar: "الْمُبْدِئُ", tr: "Al-Mubdiʾ", bn: "আল-মুবদি", en: "The Originator", meaningBn: "সূচনাকারী", detailBn: "‘মুবদি’ অর্থ সূচনাকারী। তিনি প্রথমবার সৃষ্টি শুরু করেছেন, কোনো পূর্ব নমুনা ছাড়াই। যিনি প্রথমে সৃষ্টি করেছেন, তাঁর জন্য পুনরায় সৃষ্টি করা আরও সহজ।", lessonBn: "শূন্য থেকে সৃষ্টিকারীর কাছে কিছুই অসম্ভব নয়, এ কথা ভরসার উৎস হোক।", quran: [{"ref": "সূরা আল-বুরূজ ৮৫:১৩", "ayat": ["85:13"], "gistBn": "নিশ্চয়ই তিনিই প্রথমবার সৃষ্টি করেন এবং পুনরায় সৃষ্টি করবেন।"}], hadith: [] },
  { n: 59, ar: "الْمُعِيدُ", tr: "Al-Muʿīd", bn: "আল-মুঈদ", en: "The Restorer", meaningBn: "পুনঃসৃষ্টিকারী", detailBn: "‘মুঈদ’ অর্থ পুনরায় ফিরিয়ে আনেন। মৃত্যুর পর তিনি সৃষ্টিকে পুনরায় জীবিত করে হিসাবের জন্য উপস্থিত করবেন। মুবদি ও মুঈদ একসাথে আখিরাতের উপর ঈমানের যুক্তি জোগায়।", lessonBn: "আখিরাতে পুনরুত্থানের উপর বিশ্বাস দৃঢ় রাখুন।", quran: [{"ref": "সূরা আল-বুরূজ ৮৫:১৩", "ayat": ["85:13"], "gistBn": "নিশ্চয়ই তিনিই প্রথমবার সৃষ্টি করেন এবং পুনরায় সৃষ্টি করবেন।"}], hadith: [] },
  { n: 60, ar: "الْمُحْيِي", tr: "Al-Muḥyī", bn: "আল-মুহয়ী", en: "The Giver of Life", meaningBn: "জীবনদাতা", detailBn: "‘মুহয়ী’ অর্থ জীবনদাতা। তিনি প্রাণহীন থেকে প্রাণ দেন এবং মৃত জমিনকে বৃষ্টি দিয়ে সজীব করেন। এটি কিয়ামতে পুনরুত্থানেরও একটি নিদর্শন।", lessonBn: "শুষ্ক জমিনে সবুজ দেখলে পুনরুত্থানের কথা স্মরণ করুন।", quran: [{"ref": "সূরা আর-রূম ৩০:৫০", "ayat": ["30:50"], "gistBn": "আল্লাহর রহমতের নিদর্শন দেখো, কীভাবে তিনি মৃত্যুর পর জমিনকে জীবিত করেন; তিনিই মৃতদের জীবিত করবেন।"}, {"ref": "সূরা আল-বাকারা ২:২৬০", "ayat": ["2:260"], "gistBn": "ইবরাহীম (আ.)-এর পাখির ঘটনা।"}], hadith: [], story: { title: "ইবরাহীম (আ.) ও চারটি পাখি", textBn: "ইবরাহীম (আ.) আল্লাহর কাছে চাইলেন, মৃতকে কীভাবে জীবিত করেন তা দেখাতে। আল্লাহ চারটি পাখি পোষ মানিয়ে টুকরো করে বিভিন্ন পাহাড়ে রাখতে বললেন, তারপর ডাকতে বললেন। পাখিগুলো জীবিত হয়ে তাঁর কাছে ছুটে এল। (সূরা আল-বাকারা ২:২৬০)" } },
  { n: 61, ar: "الْمُمِيتُ", tr: "Al-Mumīt", bn: "আল-মুমীত", en: "The Bringer of Death", meaningBn: "মৃত্যুদাতা", detailBn: "‘মুমীত’ অর্থ মৃত্যুদাতা। জীবন ও মৃত্যু দুটোই তাঁর হাতে। প্রতিটি প্রাণের নির্ধারিত সময়ে তিনি প্রাণ নেন, এক মুহূর্ত আগে বা পরে নয়।", lessonBn: "মৃত্যুকে স্মরণ করে প্রস্তুতি নিন।", quran: [{"ref": "সূরা আন-নাজম ৫৩:৪৪", "ayat": ["53:44"], "gistBn": "আর তিনিই মৃত্যু দেন এবং জীবন দেন।"}], hadith: [] },
  { n: 62, ar: "الْحَيُّ", tr: "Al-Ḥayy", bn: "আল-হাইয়্যু", en: "The Ever-Living", meaningBn: "চিরঞ্জীব", detailBn: "‘হাইয়্যু’ অর্থ চিরঞ্জীব। তাঁর জীবন পরিপূর্ণ, শুরু বা শেষহীন। সব সৃষ্টি মরণশীল, তিনি মরেন না। এ কারণে তাওয়াক্কুল করা হয় চিরঞ্জীবের উপর।", lessonBn: "বিপদে ‘ইয়া হাইয়্যু ইয়া কাইয়্যুম’ বলে আল্লাহর কাছে সাহায্য চান।", quran: [{"ref": "সূরা আল-বাকারা ২:২৫৫", "ayat": ["2:255"], "gistBn": "আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই; তিনি চিরঞ্জীব, চিরস্থায়ী ধারক।"}, {"ref": "সূরা আল-ফুরকান ২৫:৫৮", "ayat": ["25:58"], "gistBn": "তুমি ভরসা করো সেই চিরঞ্জীবের উপর, যিনি মরেন না।"}], hadith: [{"src": "জামে তিরমিযি ৩৫২৪", "textBn": "আনাস (রা.) বলেন, কোনো বিষয়ে নবী ﷺ-কে পেরেশান করলে তিনি বলতেন, ‘ইয়া হাইয়্যু ইয়া কাইয়্যূমু বিরাহমাতিকা আসতাগীস’ (হে চিরঞ্জীব, হে চিরস্থায়ী ধারক, আপনার রহমতের উসিলায় সাহায্য চাই)।"}] },
  { n: 63, ar: "الْقَيُّومُ", tr: "Al-Qayyūm", bn: "আল-কাইয়্যূম", en: "The Self-Sustaining", meaningBn: "চিরস্থায়ী ধারক", detailBn: "‘কাইয়্যূম’ অর্থ যিনি নিজে স্বয়ংসম্পূর্ণ এবং সবকিছুকে ধারণ ও পরিচালনা করেন। আসমান-জমিন ও সৃষ্টিজগতের স্থিতি তাঁরই উপর নির্ভরশীল। ‘হাইয়্যু’ ও ‘কাইয়্যূম’ প্রায়ই একসাথে আসে, আলেমদের মতে এ দুটিতে আল্লাহর ইসমে আযমের ইঙ্গিত আছে।", lessonBn: "সবকিছুর স্থিতি আল্লাহর হাতে; তাঁর উপরেই নির্ভর করুন।", quran: [{"ref": "সূরা আলে ইমরান ৩:২", "ayat": ["3:2"], "gistBn": "আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই; তিনি চিরঞ্জীব, চিরস্থায়ী ধারক।"}, {"ref": "সূরা ত্বা-হা ২০:১১১", "ayat": ["20:111"], "gistBn": "সব মুখ চিরঞ্জীব ও চিরস্থায়ী ধারকের সামনে অবনত হবে; আর যে জুলুমের বোঝা বহন করবে সে ব্যর্থ হবে।"}], hadith: [{"src": "জামে তিরমিযি ৩৫২৪", "textBn": "নবী ﷺ বিপদে বলতেন, ‘ইয়া হাইয়্যু ইয়া কাইয়্যূমু বিরাহমাতিকা আসতাগীস’।"}] },
  { n: 64, ar: "الْوَاجِدُ", tr: "Al-Wājid", bn: "আল-ওয়াজিদ", en: "The Finder", meaningBn: "সর্বপ্রাপ্ত", detailBn: "‘ওয়াজিদ’ অর্থ সর্বপ্রাপ্ত। তিনি যা চান সবই তাঁর কাছে আছে; কোনো কিছুর অভাব বা অনুপস্থিতি তাঁকে স্পর্শ করে না। তিনি যাকে ইচ্ছা দান করেন, নিজে কারো মুখাপেক্ষী নন।", lessonBn: "সব প্রয়োজনের জন্য সেই সর্বপ্রাপ্তের কাছেই চান।", quran: [], hadith: [] },
  { n: 65, ar: "الْمَاجِدُ", tr: "Al-Mājid", bn: "আল-মাজিদ", en: "The Noble", meaningBn: "সম্মানিত, গৌরবময়", detailBn: "‘মাজিদ’ অর্থ মহত্ত্ব ও দানশীলতায় পরিপূর্ণ, গৌরবময়। এটি ‘মাজীদ’ নামের কাছাকাছি অর্থের একটি নাম, যা প্রচলিত কিছু তালিকায় আলাদাভাবে এসেছে। এর অর্থ সম্মান ও মর্যাদায় তাঁর পরিপূর্ণতা।", lessonBn: "আল্লাহর মহিমার সামনে বিনয়ী ও কৃতজ্ঞ থাকুন।", quran: [], hadith: [] },
  { n: 66, ar: "الْوَاحِدُ", tr: "Al-Wāḥid", bn: "আল-ওয়াহিদ", en: "The One", meaningBn: "এক, অদ্বিতীয়", detailBn: "‘ওয়াহিদ’ অর্থ এক ও অদ্বিতীয়। সত্তা, গুণ ও ইবাদতের অধিকারে তাঁর কোনো শরিক নেই। তাওহীদ বা একত্ববাদ ইসলামের মূল ভিত্তি।", lessonBn: "একমাত্র আল্লাহর ইবাদত করুন এবং কাউকে তাঁর শরিক করবেন না।", quran: [{"ref": "সূরা আল-বাকারা ২:১৬৩", "ayat": ["2:163"], "gistBn": "তোমাদের ইলাহ এক ইলাহ; তিনি ছাড়া কোনো ইলাহ নেই, তিনি পরম করুণাময়, অতি দয়ালু।"}], hadith: [] },
  { n: 67, ar: "الْأَحَدُ", tr: "Al-Aḥad", bn: "আল-আহাদ", en: "The Unique", meaningBn: "একক", detailBn: "‘আহাদ’ অর্থ একক, যাঁর কোনো সমকক্ষ বা তুলনা নেই। ‘ওয়াহিদ’ সংখ্যায় এক বোঝায়, আর ‘আহাদ’ বোঝায় তিনি সত্তা ও গুণে অনন্য ও অবিভাজ্য। এ নামটি সূরা ইখলাসের ভিত্তি।", lessonBn: "সূরা ইখলাসের অর্থ জেনে নিয়মিত তিলাওয়াত করুন।", quran: [{"ref": "সূরা আল-ইখলাস ১১২:১", "ayat": ["112:1"], "gistBn": "বলুন, তিনি আল্লাহ, এক।"}], hadith: [{"src": "সহীহ বুখারি ৫০১৩", "textBn": "এক ব্যক্তি রাতে বারবার ‘কুল হুওয়াল্লাহু আহাদ’ পড়ছিলেন। নবী ﷺ-কে জানানো হলে তিনি বললেন, যাঁর হাতে আমার প্রাণ, এটি কুরআনের এক-তৃতীয়াংশের সমান।"}] },
  { n: 68, ar: "الصَّمَدُ", tr: "Aṣ-Ṣamad", bn: "আস-সামাদ", en: "The Eternal Refuge", meaningBn: "অমুখাপেক্ষী", detailBn: "‘সামাদ’ অর্থ যিনি কারো মুখাপেক্ষী নন, কিন্তু সবাই সব প্রয়োজনে তাঁর মুখাপেক্ষী। বিপদে-আপদে সবাই তাঁর দিকেই ফিরে যায়। তিনি পানাহারের ঊর্ধ্বে ও স্বয়ংসম্পূর্ণ।", lessonBn: "প্রয়োজনে মানুষের আগে আল্লাহর কাছে হাত তুলুন।", quran: [{"ref": "সূরা আল-ইখলাস ১১২:২", "ayat": ["112:2"], "gistBn": "আল্লাহ অমুখাপেক্ষী।"}], hadith: [] },
  { n: 69, ar: "الْقَادِرُ", tr: "Al-Qādir", bn: "আল-কাদির", en: "The Capable", meaningBn: "সর্বশক্তিমান", detailBn: "‘কাদির’ অর্থ সর্বশক্তিমান। যা চান তা করতে তিনি সম্পূর্ণ সক্ষম, কোনো কিছু তাঁকে অক্ষম করতে পারে না। তাঁর ইচ্ছা মাত্র ‘হও’ বললেই হয়ে যায়।", lessonBn: "কোনো সমস্যাকে আল্লাহর ক্ষমতার চেয়ে বড় ভাববেন না।", quran: [{"ref": "সূরা আল-আনআম ৬:৬৫", "ayat": ["6:65"], "gistBn": "বলুন, তিনি তোমাদের উপর শাস্তি পাঠাতে সক্ষম।"}], hadith: [] },
  { n: 70, ar: "الْمُقْتَدِرُ", tr: "Al-Muqtadir", bn: "আল-মুকতাদির", en: "The Omnipotent", meaningBn: "পূর্ণ ক্ষমতাবান", detailBn: "‘মুকতাদির’ অর্থ পূর্ণ ক্ষমতাবান। ‘কাদির’ ক্ষমতা থাকার কথা বলে, ‘মুকতাদির’ বলে সেই ক্ষমতা পূর্ণ ও প্রবলভাবে প্রয়োগ করার কথা। কেউ তাঁর ইচ্ছাকে বাধা দিতে পারে না।", lessonBn: "জালিমের শক্তি দেখে হতাশ হবেন না; আল্লাহ সবচেয়ে ক্ষমতাবান।", quran: [{"ref": "সূরা আল-কামার ৫৪:৫৫", "ayat": ["54:55"], "gistBn": "যোগ্য আসনে, সর্বক্ষমতাবান মালিকের সান্নিধ্যে।"}, {"ref": "সূরা আল-কাহফ ১৮:৪৫", "ayat": ["18:45"], "gistBn": "আল্লাহ সবকিছুর উপর ক্ষমতাবান।"}], hadith: [] },
  { n: 71, ar: "الْمُقَدِّمُ", tr: "Al-Muqaddim", bn: "আল-মুকাদ্দিম", en: "The Expediter", meaningBn: "অগ্রবর্তীকারী", detailBn: "‘মুকাদ্দিম’ অর্থ যিনি যাকে ইচ্ছা এগিয়ে দেন। তিনি নিজ হিকমতে কাউকে মর্যাদা, সময় বা সুযোগে অগ্রবর্তী করেন। কে কখন কী পাবে, তা তাঁরই সিদ্ধান্ত।", lessonBn: "অন্যের এগিয়ে যাওয়া দেখে হিংসা না করে আল্লাহর কাছে নিজের জন্য কল্যাণ চান।", quran: [], hadith: [{"src": "সহীহ বুখারি ৬৩৯৮, সহীহ মুসলিম ২৭১৯", "textBn": "নবী ﷺ দুআয় বলতেন, ‘আপনিই অগ্রবর্তীকারী এবং আপনিই পশ্চাদবর্তীকারী, আপনি ছাড়া কোনো ইলাহ নেই।’"}] },
  { n: 72, ar: "الْمُؤَخِّرُ", tr: "Al-Muʾakhkhir", bn: "আল-মুআখখির", en: "The Delayer", meaningBn: "পশ্চাদবর্তীকারী", detailBn: "‘মুআখখির’ অর্থ যিনি যাকে ইচ্ছা পিছিয়ে দেন বা বিলম্বিত করেন। কখনো কোনো প্রাপ্তি দেরিতে আসে, কারণ তাতে বান্দার কল্যাণ নিহিত থাকে। মুকাদ্দিম ও মুআখখির একসাথে স্মরণ করলে আল্লাহর হিকমতপূর্ণ নিয়ন্ত্রণ বোঝা যায়।", lessonBn: "দুআ কবুলে দেরি হলে ধৈর্য ধরুন; আল্লাহ সঠিক সময়ই জানেন।", quran: [], hadith: [{"src": "সহীহ বুখারি ৬৩৯৮, সহীহ মুসলিম ২৭১৯", "textBn": "নবী ﷺ দুআয় বলতেন, ‘আপনিই অগ্রবর্তীকারী এবং আপনিই পশ্চাদবর্তীকারী, আপনি ছাড়া কোনো ইলাহ নেই।’"}] },
  { n: 73, ar: "الْأَوَّلُ", tr: "Al-Awwal", bn: "আল-আওয়াল", en: "The First", meaningBn: "সর্বপ্রথম", detailBn: "‘আউয়াল’ অর্থ সর্বপ্রথম, যাঁর আগে কিছুই ছিল না। সৃষ্টির শুরু আছে, কিন্তু আল্লাহর কোনো শুরু নেই। তিনি অনাদি।", lessonBn: "আল্লাহর অনাদি সত্তার কথা ভেবে দুনিয়ার ক্ষণস্থায়ী বিষয়ে আসক্তি কমান।", quran: [{"ref": "সূরা আল-হাদীদ ৫৭:৩", "ayat": ["57:3"], "gistBn": "তিনিই প্রথম, তিনিই শেষ, তিনিই প্রকাশ্য, তিনিই গোপন।"}], hadith: [{"src": "সহীহ মুসলিম ২৭১৩", "textBn": "ঘুমানোর দুআয় নবী ﷺ বলতেন, ‘আপনিই প্রথম, আপনার আগে কিছুই নেই; আপনিই শেষ, আপনার পরে কিছুই নেই।’"}] },
  { n: 74, ar: "الْآخِرُ", tr: "Al-Ākhir", bn: "আল-আখির", en: "The Last", meaningBn: "সর্বশেষ", detailBn: "‘আখির’ অর্থ সর্বশেষ, যাঁর পরে কিছুই অবশিষ্ট থাকবে না। সবকিছু ধ্বংস হয়ে যাবে, কিন্তু তিনি চিরকাল থাকবেন। এ নাম আমাদের স্মরণ করিয়ে দেয়, ফিরে যেতে হবে তাঁরই কাছে।", lessonBn: "প্রতিটি কাজে আখিরাতকে সামনে রাখুন।", quran: [{"ref": "সূরা আল-হাদীদ ৫৭:৩", "ayat": ["57:3"], "gistBn": "তিনিই প্রথম, তিনিই শেষ, তিনিই প্রকাশ্য, তিনিই গোপন।"}], hadith: [{"src": "সহীহ মুসলিম ২৭১৩", "textBn": "ঘুমানোর দুআয় নবী ﷺ বলতেন, ‘আপনিই প্রথম, আপনার আগে কিছুই নেই; আপনিই শেষ, আপনার পরে কিছুই নেই।’"}] },
  { n: 75, ar: "الظَّاهِرُ", tr: "Aẓ-Ẓāhir", bn: "আয-যাহির", en: "The Manifest", meaningBn: "প্রকাশমান", detailBn: "‘যাহির’ অর্থ প্রকাশমান ও সর্বোচ্চ। তাঁর অস্তিত্বের নিদর্শন আসমান-জমিনের সবখানে স্পষ্ট এবং মর্যাদায় তাঁর উপরে কেউ নেই।", lessonBn: "সৃষ্টির নিদর্শনে আল্লাহকে চিনতে শিখুন।", quran: [{"ref": "সূরা আল-হাদীদ ৫৭:৩", "ayat": ["57:3"], "gistBn": "তিনিই প্রথম, তিনিই শেষ, তিনিই প্রকাশ্য, তিনিই গোপন।"}], hadith: [{"src": "সহীহ মুসলিম ২৭১৩", "textBn": "ঘুমানোর দুআয় নবী ﷺ বলতেন, ‘আপনিই প্রকাশমান, আপনার উপরে কিছুই নেই; আপনিই গোপন, আপনার নিচে কিছুই নেই।’"}] },
  { n: 76, ar: "الْبَاطِنُ", tr: "Al-Bāṭin", bn: "আল-বাতিন", en: "The Hidden", meaningBn: "গোপন, নিকটবর্তী", detailBn: "‘বাতিন’ অর্থ গোপন, যিনি সৃষ্টির অন্তরের গোপন বিষয় জানেন। আলেমদের ব্যাখ্যায় তিনি অতি নিকটবর্তী, কোনো কিছুই তাঁর জ্ঞানের বাইরে নয়। চোখ তাঁকে দুনিয়ায় দেখতে পায় না, কিন্তু তিনি সবকিছুর খবর রাখেন।", lessonBn: "অন্তরের গোপন চিন্তাও আল্লাহ জানেন, তাই মন পরিষ্কার রাখুন।", quran: [{"ref": "সূরা আল-হাদীদ ৫৭:৩", "ayat": ["57:3"], "gistBn": "তিনিই প্রথম, তিনিই শেষ, তিনিই প্রকাশ্য, তিনিই গোপন।"}], hadith: [{"src": "সহীহ মুসলিম ২৭১৩", "textBn": "ঘুমানোর দুআয় নবী ﷺ বলতেন, ‘আপনিই প্রকাশমান, আপনার উপরে কিছুই নেই; আপনিই গোপন, আপনার নিচে কিছুই নেই।’"}] },
  { n: 77, ar: "الْوَالِي", tr: "Al-Wālī", bn: "আল-ওয়ালী", en: "The Governor", meaningBn: "শাসক, পরিচালক", detailBn: "‘ওয়ালী’ এখানে শাসক ও পরিচালক অর্থে এসেছে। সৃষ্টিজগতের সব বিষয় তিনি পরিচালনা করেন এবং মুমিনদের অভিভাবক হিসেবে সাহায্য করেন। তাঁর ছাড়া অন্য কোনো অভিভাবক নেই।", lessonBn: "বিপদে মানুষের উপর নয়, আল্লাহর উপর নির্ভর করুন।", quran: [{"ref": "সূরা আর-রা’দ ১৩:১১", "ayat": ["13:11"], "gistBn": "তিনি ছাড়া তাদের কোনো অভিভাবক নেই।"}, {"ref": "সূরা আশ-শূরা ৪২:২৮", "ayat": ["42:28"], "gistBn": "তিনিই অভিভাবক, প্রশংসিত।"}], hadith: [] },
  { n: 78, ar: "الْمُتَعَالِي", tr: "Al-Mutaʿālī", bn: "আল-মুতাআলী", en: "The Most Exalted", meaningBn: "সুউচ্চ মর্যাদাবান", detailBn: "‘মুতাআলী’ অর্থ সুউচ্চ মর্যাদাবান, যিনি সৃষ্টির সব গুণাবলি ও সাদৃশ্যের ঊর্ধ্বে। তাঁর মহত্ত্ব কোনো তুলনার মধ্যে আসে না।", lessonBn: "আল্লাহকে সৃষ্টির মতো কল্পনা না করে তাঁর মহত্ত্ব স্বীকার করুন।", quran: [{"ref": "সূরা আর-রা’দ ১৩:৯", "ayat": ["13:9"], "gistBn": "তিনি অদৃশ্য ও দৃশ্যের জ্ঞানী, মহান, সর্বোচ্চ মর্যাদাবান।"}], hadith: [] },
  { n: 79, ar: "الْبَرُّ", tr: "Al-Barr", bn: "আল-বার", en: "The Source of Goodness", meaningBn: "পরম কল্যাণকারী", detailBn: "‘বার’ অর্থ পরম কল্যাণকারী ও অনুগ্রহশীল। তিনি বান্দার প্রতি অত্যন্ত দয়া করেন এবং তাঁর প্রতিশ্রুতি পূর্ণ করেন। এ নাম তাঁর অনুগ্রহের পূর্ণতা বোঝায়।", lessonBn: "আল্লাহর কল্যাণের শুকরিয়া হিসেবে মা-বাবা ও অন্যদের প্রতি সদাচরণ করুন।", quran: [{"ref": "সূরা আত-তূর ৫২:২৮", "ayat": ["52:28"], "gistBn": "নিশ্চয়ই তিনি পরম কল্যাণকারী, অতি দয়ালু।"}], hadith: [] },
  { n: 80, ar: "التَّوَّابُ", tr: "At-Tawwāb", bn: "আত-তাওয়াব", en: "The Accepter of Repentance", meaningBn: "তওবা কবুলকারী", detailBn: "‘তাওয়াব’ অর্থ বারবার তওবা কবুলকারী। বান্দা বারবার ফিরে এলেও তিনি ফিরিয়ে দেন না, বরং তওবায় খুশি হন। আদম (আ.)-এর তওবা কবুল হওয়া এ নামেরই প্রকাশ।", lessonBn: "গুনাহ হলে দেরি না করে তওবা করুন; তাঁর দরজা সবসময় খোলা।", quran: [{"ref": "সূরা আল-বাকারা ২:৩৭", "ayat": ["2:37"], "gistBn": "আদম তার রবের কাছ থেকে কিছু বাক্য পেলেন এবং তিনি তার তওবা কবুল করলেন; নিশ্চয়ই তিনি তাওয়াব, রাহীম।"}, {"ref": "সূরা আত-তাওবা ৯:১০৪", "ayat": ["9:104"], "gistBn": "আল্লাহই তাঁর বান্দাদের তওবা কবুল করেন।"}], hadith: [{"src": "সহীহ বুখারি ৬৩০৮, সহীহ মুসলিম ২৭৪৪", "textBn": "নবী ﷺ বলেন, মরুভূমিতে উট হারিয়ে ফেলা ব্যক্তি তা ফিরে পেলে যত খুশি হয়, বান্দার তওবায় আল্লাহ তার চেয়েও বেশি খুশি হন।"}], story: { title: "আদম (আ.)", textBn: "আদম (আ.) ও হাওয়া (আ.) নিষিদ্ধ গাছের কাছে গিয়ে ভুল করলেন। তাঁরা দুআ করলেন, ‘হে আমাদের রব! আমরা নিজেদের উপর জুলুম করেছি…’ আল্লাহ তাঁদের তওবা কবুল করলেন।" } },
  { n: 81, ar: "الْمُنْتَقِمُ", tr: "Al-Muntaqim", bn: "আল-মুনতাকিম", en: "The Avenger", meaningBn: "প্রতিশোধ গ্রহণকারী", detailBn: "‘মুনতাকিম’ অর্থ প্রতিশোধ গ্রহণকারী, যিনি জালিম ও অবাধ্যদের ন্যায্য শাস্তি দেন। এটি তাঁর ন্যায়বিচারের অংশ। বান্দার জন্য এ নাম একদিকে সতর্কতা, অন্যদিকে নির্যাতিতের জন্য সান্ত্বনা।", lessonBn: "জুলুম থেকে বিরত থাকুন এবং মজলুম হলে আল্লাহর ন্যায়বিচারে ভরসা রাখুন।", quran: [{"ref": "সূরা আস-সাজদা ৩২:২২", "ayat": ["32:22"], "gistBn": "নিশ্চয়ই আমি অপরাধীদের কাছ থেকে প্রতিশোধ নেব।"}, {"ref": "সূরা আয-যুখরুফ ৪৩:৪১", "ayat": ["43:41"], "gistBn": "আমি অবশ্যই তাদের কাছ থেকে প্রতিশোধ নেব।"}], hadith: [] },
  { n: 82, ar: "الْعَفُوُّ", tr: "Al-ʿAfuww", bn: "আল-আফুউ", en: "The Pardoner", meaningBn: "মার্জনাকারী", detailBn: "‘আফুউ’ অর্থ মার্জনাকারী, যিনি গুনাহ কেবল ক্ষমা নয়, বরং মুছে দেন। ‘গাফূর’ গুনাহ ঢেকে রাখে, ‘আফুউ’ তার চিহ্নও মিটিয়ে দেয়। লাইলাতুল কদরে এ নামে দুআ করতে নবী ﷺ শিখিয়েছেন।", lessonBn: "রমযানের শেষ দশকে ‘আল্লাহুম্মা ইন্নাকা আফুউউন…’ দুআটি বেশি করে পড়ুন।", quran: [{"ref": "সূরা আন-নিসা ৪:১৪৯", "ayat": ["4:149"], "gistBn": "নিশ্চয়ই আল্লাহ মার্জনাকারী, সর্বশক্তিমান।"}, {"ref": "সূরা আল-হাজ্জ ২২:৬০", "ayat": ["22:60"], "gistBn": "নিশ্চয়ই আল্লাহ মার্জনাকারী, পরম ক্ষমাশীল।"}], hadith: [{"src": "জামে তিরমিযি ৩৫১৩", "textBn": "আয়েশা (রা.) জিজ্ঞেস করলেন, লাইলাতুল কদর পেলে কী বলব? নবী ﷺ বললেন, বলো, ‘আল্লাহুম্মা ইন্নাকা আফুউউন, তুহিব্বুল আফওয়া, ফা’ফু আন্নী’।"}] },
  { n: 83, ar: "الرَّؤُوفُ", tr: "Ar-Raʾūf", bn: "আর-রাউফ", en: "The Most Kind", meaningBn: "অতি স্নেহশীল", detailBn: "‘রাঊফ’ অর্থ অতি স্নেহশীল ও কোমল। ‘রাহীম’-এর চেয়ে এ নামে আরও গভীর কোমলতা ও মমতার ভাব আছে। তিনি বান্দার কষ্ট লাঘব করেন এবং সামর্থ্যের বাইরে বোঝা চাপান না।", lessonBn: "নিজের আচরণে অন্যের প্রতি কোমলতা ও স্নেহ প্রকাশ করুন।", quran: [{"ref": "সূরা আল-বাকারা ২:১৪৩", "ayat": ["2:143"], "gistBn": "নিশ্চয়ই আল্লাহ মানুষের প্রতি অতি স্নেহশীল, পরম দয়ালু।"}, {"ref": "সূরা আলে ইমরান ৩:৩০", "ayat": ["3:30"], "gistBn": "আল্লাহ বান্দাদের প্রতি অতি স্নেহশীল।"}], hadith: [] },
  { n: 84, ar: "مَالِكُ الْمُلْكِ", tr: "Mālik-ul-Mulk", bn: "মালিকুল মুলক", en: "Owner of Sovereignty", meaningBn: "রাজত্বের মালিক", detailBn: "‘মালিকুল মুলক’ অর্থ রাজত্বের মালিক। দুনিয়ার সব ক্ষমতা ও রাজত্ব তাঁর হাতে, তিনি যাকে ইচ্ছা তা দেন এবং যার কাছ থেকে ইচ্ছা কেড়ে নেন। যারা রাজ্য পায় তারা কেবল আমানতদার।", lessonBn: "ক্ষমতা বা সম্পদ হারালে আফসোস না করে আল্লাহর ফয়সালায় সন্তুষ্ট থাকুন।", quran: [{"ref": "সূরা আলে ইমরান ৩:২৬", "ayat": ["3:26"], "gistBn": "বলো, হে রাজত্বের মালিক আল্লাহ! আপনি যাকে ইচ্ছা রাজত্ব দেন এবং যার কাছ থেকে ইচ্ছা কেড়ে নেন; আপনি যাকে ইচ্ছা সম্মান দেন এবং যাকে ইচ্ছা অপমান করেন।"}], hadith: [] },
  { n: 85, ar: "ذُو الْجَلَالِ وَالْإِكْرَامِ", tr: "Dhul-Jalāli wal-Ikrām", bn: "যুল জালালি ওয়াল ইকরাম", en: "Lord of Majesty and Honor", meaningBn: "মহিমা ও সম্মানের অধিকারী", detailBn: "‘যুল জালালি ওয়াল ইকরাম’ অর্থ মহিমা ও সম্মানের অধিকারী। ‘জালাল’ তাঁর প্রতাপ ও মহত্ত্ব, ‘ইকরাম’ তাঁর দয়া ও সম্মান দানের গুণ। দুআ করার সময় এ নামে ডাকা উত্তম।", lessonBn: "দুআর শুরুতে আল্লাহর এই মহিমান্বিত নাম নিয়ে তাঁকে ডাকুন।", quran: [{"ref": "সূরা আর-রাহমান ৫৫:২৭", "ayat": ["55:27"], "gistBn": "আপনার রবের চেহারা বাকি থাকবে, যিনি মহিমা ও সম্মানের অধিকারী।"}, {"ref": "সূরা আর-রাহমান ৫৫:৭৮", "ayat": ["55:78"], "gistBn": "বরকতময় আপনার রবের নাম, যিনি মহিমা ও সম্মানের অধিকারী।"}], hadith: [] },
  { n: 86, ar: "الْمُقْسِطُ", tr: "Al-Muqsiṭ", bn: "আল-মুকসিত", en: "The Equitable", meaningBn: "ন্যায়পরায়ণ", detailBn: "‘মুকসিত’ অর্থ ন্যায়পরায়ণ, যিনি সঠিকভাবে ইনসাফ প্রতিষ্ঠা করেন এবং মজলুমের অধিকার ফিরিয়ে দেন। যারা ন্যায়বিচার করে তাদের তিনি ভালোবাসেন।", lessonBn: "পরিবার, কর্মক্ষেত্র ও সমাজে ইনসাফ বজায় রাখুন।", quran: [{"ref": "সূরা আল-মায়িদা ৫:৪২", "ayat": ["5:42"], "gistBn": "নিশ্চয়ই আল্লাহ ন্যায়বিচারকারীদের ভালোবাসেন।"}, {"ref": "সূরা আলে ইমরান ৩:১৮", "ayat": ["3:18"], "gistBn": "আল্লাহ সাক্ষ্য দেন যে তিনি ছাড়া কোনো ইলাহ নেই, তিনি ন্যায়ের উপর প্রতিষ্ঠিত।"}], hadith: [] },
  { n: 87, ar: "الْجَامِعُ", tr: "Al-Jāmiʿ", bn: "আল-জামি", en: "The Gatherer", meaningBn: "একত্রকারী", detailBn: "‘জামি’ অর্থ একত্রকারী। কিয়ামতের দিন তিনি আদি থেকে অন্ত পর্যন্ত সব মানুষকে একত্র করবেন এবং হিসাব নেবেন। তিনি বিচ্ছিন্ন জিনিসকেও একত্রিত করতে সক্ষম।", lessonBn: "কিয়ামতের জমায়েতের কথা মনে রেখে আজই প্রস্তুতি নিন।", quran: [{"ref": "সূরা আলে ইমরান ৩:৯", "ayat": ["3:9"], "gistBn": "হে আমাদের রব! আপনি অবশ্যই মানুষকে এমন এক দিনে একত্র করবেন, যাতে কোনো সন্দেহ নেই।"}], hadith: [] },
  { n: 88, ar: "الْغَنِيُّ", tr: "Al-Ghaniyy", bn: "আল-গানী", en: "The Self-Sufficient", meaningBn: "অভাবমুক্ত, ধনী", detailBn: "‘গানী’ অর্থ অভাবমুক্ত। তিনি কারো মুখাপেক্ষী নন; সমস্ত সৃষ্টি তাঁর মুখাপেক্ষী। বান্দার ইবাদত তাঁর কোনো লাভ বা ক্ষতি করে না, বরং কল্যাণ বান্দারই।", lessonBn: "সব প্রয়োজনে একমাত্র আল্লাহর মুখাপেক্ষী হোন।", quran: [{"ref": "সূরা ফাতির ৩৫:১৫", "ayat": ["35:15"], "gistBn": "হে মানুষ! তোমরা আল্লাহর মুখাপেক্ষী; আল্লাহই অভাবমুক্ত, প্রশংসিত।"}], hadith: [] },
  { n: 89, ar: "الْمُغْنِي", tr: "Al-Mughnī", bn: "আল-মুগনী", en: "The Enricher", meaningBn: "অভাবমোচনকারী", detailBn: "‘মুগনী’ অর্থ অভাবমোচনকারী, যিনি যাকে ইচ্ছা অভাবমুক্ত করেন ও সম্পদ দেন। সম্পদ আসে তাঁর অনুগ্রহ থেকে, বান্দার শক্তি বা কৌশল থেকে নয়।", lessonBn: "অভাবে আল্লাহর কাছে চান এবং ধৈর্য ধরুন।", quran: [{"ref": "সূরা আন-নাজম ৫৩:৪৮", "ayat": ["53:48"], "gistBn": "এবং তিনিই অভাবমুক্ত করেন ও সম্পদ দান করেন।"}, {"ref": "সূরা আত-তাওবা ৯:২৮", "ayat": ["9:28"], "gistBn": "আল্লাহ চাইলে নিজ অনুগ্রহে তোমাদের অভাবমুক্ত করবেন।"}], hadith: [] },
  { n: 90, ar: "الْمَانِعُ", tr: "Al-Māniʿ", bn: "আল-মানি", en: "The Withholder", meaningBn: "প্রতিরোধকারী", detailBn: "‘মানি’ অর্থ প্রতিরোধকারী, যিনি হিকমত অনুযায়ী কিছু আটকে রাখেন। যা তিনি দেন তা কেউ আটকাতে পারে না, যা আটকান তা কেউ দিতে পারে না। যা পাওয়া হয়নি তাতেও বান্দার কল্যাণ থাকতে পারে।", lessonBn: "না পাওয়ার আফসোসে না থেকে আল্লাহর ফয়সালায় সন্তুষ্ট থাকুন।", quran: [], hadith: [{"src": "সহীহ বুখারি ৮৪৪, সহীহ মুসলিম ৫৯৩", "textBn": "নামাজের পর নবী ﷺ বলতেন, ‘হে আল্লাহ! আপনি যা দেন তা আটকানোর কেউ নেই এবং আপনি যা আটকান তা দেওয়ার কেউ নেই।’"}] },
  { n: 91, ar: "الضَّارُّ", tr: "Aḍ-Ḍārr", bn: "আয-যার", en: "The Distresser", meaningBn: "ক্ষতিদাতা", detailBn: "‘যার’ অর্থ ক্ষতিদাতা। আল্লাহর অনুমতি ছাড়া কেউ কারো ক্ষতি করতে পারে না। এটি তাঁর ক্ষমতার পূর্ণতা বোঝায়। আল্লাহ দুঃখ-কষ্টও দেন পরীক্ষা ও হিকমতের জন্য।", lessonBn: "ক্ষতির ভয়ে মানুষকে নয়, একমাত্র আল্লাহকে ভয় করুন।", quran: [{"ref": "সূরা আল-আনআম ৬:১৭", "ayat": ["6:17"], "gistBn": "আল্লাহ যদি তোমাকে কোনো কষ্ট দেন, তবে তিনি ছাড়া তা দূর করার কেউ নেই।"}, {"ref": "সূরা ইউনুস ১০:১০৭", "ayat": ["10:107"], "gistBn": "আল্লাহ তোমাকে কষ্ট দিলে তিনি ছাড়া তা দূর করার কেউ নেই।"}], hadith: [{"src": "জামে তিরমিযি ২৫১৬", "textBn": "নবী ﷺ ইবনে আব্বাস (রা.)-কে বলেন, জেনে রাখো, সমস্ত উম্মত যদি তোমার ক্ষতি করতে একত্র হয়, আল্লাহ যা লিখে রেখেছেন তার বেশি তারা ক্ষতি করতে পারবে না।"}] },
  { n: 92, ar: "النَّافِعُ", tr: "An-Nāfiʿ", bn: "আন-নাফি", en: "The Benefactor", meaningBn: "উপকারদাতা", detailBn: "‘নাফি’ অর্থ উপকারদাতা। সব কল্যাণ ও উপকার তাঁর ইচ্ছাতেই আসে। মানুষ শুধু মাধ্যম, প্রকৃত উপকারদাতা আল্লাহ।", lessonBn: "কারো উপকার পেলে আল্লাহর শুকরিয়া আদায় করুন এবং উপকারকারীকেও ধন্যবাদ দিন।", quran: [{"ref": "সূরা ইউনুস ১০:১০৭", "ayat": ["10:107"], "gistBn": "আল্লাহ যদি তোমার কল্যাণ চান, তাঁর অনুগ্রহ রদ করার কেউ নেই।"}], hadith: [{"src": "জামে তিরমিযি ২৫১৬", "textBn": "নবী ﷺ ইবনে আব্বাস (রা.)-কে বলেন, সমস্ত উম্মত যদি তোমার উপকার করতে একত্র হয়, আল্লাহ যা লিখে রেখেছেন তার বেশি তারা উপকার করতে পারবে না।"}] },
  { n: 93, ar: "النُّورُ", tr: "An-Nūr", bn: "আন-নূর", en: "The Light", meaningBn: "আলো", detailBn: "‘নূর’ অর্থ আলো। আল্লাহ আসমান ও জমিনের নূর, অর্থাৎ তিনি সৃষ্টিকে আলোকিত করেন এবং হিদায়াতের আলো দেন। তাঁর হিদায়াত ছাড়া মানুষ অন্ধকারে পথ হারায়।", lessonBn: "কুরআন ও সুন্নাহর আলোয় জীবন পরিচালনা করুন।", quran: [{"ref": "সূরা আন-নূর ২৪:৩৫", "ayat": ["24:35"], "gistBn": "আল্লাহ আসমান ও জমিনের নূর।"}], hadith: [{"src": "সহীহ বুখারি ১১২০, সহীহ মুসলিম ৭৬৯", "textBn": "তাহাজ্জুদের দুআয় নবী ﷺ বলতেন, ‘হে আল্লাহ! সমস্ত প্রশংসা আপনার; আপনি আসমান ও জমিনের নূর।’"}] },
  { n: 94, ar: "الْهَادِي", tr: "Al-Hādī", bn: "আল-হাদী", en: "The Guide", meaningBn: "পথপ্রদর্শক", detailBn: "‘হাদী’ অর্থ পথপ্রদর্শক। তিনি বান্দাকে সত্য পথ দেখান এবং তাতে চলার তাওফীক দেন। আমরা প্রতিদিন নামাজে ‘ইহদিনাস সিরাতাল মুস্তাকীম’ বলে এ গুণের কাছেই সাহায্য চাই।", lessonBn: "প্রতি রাকাতে সূরা ফাতিহার এই দুআ মনোযোগ দিয়ে পড়ুন।", quran: [{"ref": "সূরা আল-ফাতিহা ১:৬", "ayat": ["1:6"], "gistBn": "আমাদের সরল পথ দেখান।"}, {"ref": "সূরা আল-হাজ্জ ২২:৫৪", "ayat": ["22:54"], "gistBn": "নিশ্চয়ই আল্লাহ মুমিনদের সরল পথের দিকে পরিচালিত করেন।"}], hadith: [] },
  { n: 95, ar: "الْبَدِيعُ", tr: "Al-Badīʿ", bn: "আল-বাদী", en: "The Incomparable Originator", meaningBn: "অনুপম সৃষ্টিকর্তা", detailBn: "‘বাদী’ অর্থ অনুপম সৃষ্টিকর্তা, যিনি আগের কোনো নমুনা ছাড়াই অভূতপূর্ব সৃষ্টি করেন। আসমান-জমিনের সৌন্দর্য ও বৈচিত্র্যে তাঁর এ গুণ প্রকাশিত।", lessonBn: "সৃষ্টির বৈচিত্র্য নিয়ে চিন্তা করে আল্লাহর প্রশংসা করুন।", quran: [{"ref": "সূরা আল-বাকারা ২:১১৭", "ayat": ["2:117"], "gistBn": "তিনি আসমান ও জমিনের উদ্ভাবক।"}, {"ref": "সূরা আল-আনআম ৬:১০১", "ayat": ["6:101"], "gistBn": "তিনি আসমান ও জমিনের অনুপম স্রষ্টা।"}], hadith: [] },
  { n: 96, ar: "الْبَاقِي", tr: "Al-Bāqī", bn: "আল-বাকী", en: "The Everlasting", meaningBn: "চিরস্থায়ী", detailBn: "‘বাকী’ অর্থ চিরস্থায়ী, যিনি কখনো ধ্বংস হবেন না। সবকিছু ক্ষণস্থায়ী, কেবল তিনিই অবশিষ্ট থাকবেন। এ নাম দুনিয়ার প্রতি আসক্তি কমায়।", lessonBn: "যা শেষ হয়ে যায় তার জন্য নয়, যা চিরস্থায়ী তার জন্য আমল করুন।", quran: [{"ref": "সূরা আর-রাহমান ৫৫:২৬-২৭", "ayat": ["55:26", "55:27"], "gistBn": "ভূপৃষ্ঠে যা কিছু আছে সবই নশ্বর; অবশিষ্ট থাকবে আপনার রবের চেহারা, যিনি মহিমা ও সম্মানের অধিকারী।"}, {"ref": "সূরা আল-কাসাস ২৮:৮৮", "ayat": ["28:88"], "gistBn": "তাঁর চেহারা ছাড়া সবকিছু ধ্বংসশীল।"}], hadith: [] },
  { n: 97, ar: "الْوَارِثُ", tr: "Al-Wārith", bn: "আল-ওয়ারিস", en: "The Inheritor", meaningBn: "চূড়ান্ত উত্তরাধিকারী", detailBn: "‘ওয়ারিস’ অর্থ চূড়ান্ত উত্তরাধিকারী। সবকিছু ধ্বংসের পর তিনিই অবশিষ্ট থাকবেন এবং আসমান-জমিনের মালিকানা তাঁর কাছেই ফিরে যাবে। মানুষ যা কিছু ছেড়ে যায়, তাও শেষ পর্যন্ত তাঁর কাছেই থাকে।", lessonBn: "সম্পদ ও সন্তানকে আল্লাহর আমানত মনে করুন।", quran: [{"ref": "সূরা আল-হিজর ১৫:২৩", "ayat": ["15:23"], "gistBn": "নিশ্চয়ই আমিই জীবন দিই, মৃত্যু ঘটাই এবং আমিই চূড়ান্ত উত্তরাধিকারী।"}, {"ref": "সূরা মারইয়াম ১৯:৪০", "ayat": ["19:40"], "gistBn": "নিশ্চয়ই আমিই জমিন ও তার উপর যারা আছে তাদের উত্তরাধিকারী হব।"}, {"ref": "সূরা আল-আম্বিয়া ২১:৮৯", "ayat": ["21:89"], "gistBn": "যাকারিয়্যা (আ.)-এর দুআ, ‘হে আমার রব! আমাকে একা রেখে দেবেন না, আপনিই সর্বোত্তম উত্তরাধিকারী।’"}], hadith: [], story: { title: "জাকারিয়া (আ.)", textBn: "বৃদ্ধ বয়সে সন্তানহীন যাকারিয়্যা (আ.) আল্লাহর কাছে সন্তানের জন্য দুআ করলেন এবং বললেন, ‘আপনিই সর্বোত্তম উত্তরাধিকারী।’ আল্লাহ তাঁকে ইয়াহইয়া (আ.)-কে দান করলেন।" } },
  { n: 98, ar: "الرَّشِيدُ", tr: "Ar-Rashīd", bn: "আর-রাশীদ", en: "The Guide to the Right Path", meaningBn: "সঠিক পথপ্রদর্শক", detailBn: "‘রাশীদ’ অর্থ সঠিক পথপ্রদর্শক, যিনি সব কাজ সর্বোত্তম পরিকল্পনায় পরিচালনা করেন। তাঁর সিদ্ধান্ত কখনো ভুল হয় না এবং তিনি বান্দাকে সঠিক দিকনির্দেশনা দেন।", lessonBn: "সিদ্ধান্ত নেওয়ার সময় আল্লাহর কাছে সঠিক পথের তাওফীক চান।", quran: [], hadith: [] },
  { n: 99, ar: "الصَّبُورُ", tr: "Aṣ-Ṣabūr", bn: "আস-সাবুর", en: "The Patient", meaningBn: "পরম ধৈর্যশীল", detailBn: "‘সাবুর’ অর্থ পরম ধৈর্যশীল। তিনি অবাধ্যদের শাস্তি দিতে তাড়াহুড়ো করেন না, বরং সময় দেন, যাতে তারা ফিরে আসতে পারে। তাঁর ধৈর্য ও ক্ষমার সামনে বান্দার ধৈর্য ক্ষুদ্র।", lessonBn: "কষ্টে ও রাগের সময় ধৈর্য ধরার চেষ্টা করুন এবং আল্লাহর ধৈর্য স্মরণ করুন।", quran: [], hadith: [{"src": "সহীহ বুখারি ৬০৯৯, সহীহ মুসলিম ২৮০৪", "textBn": "নবী ﷺ বলেন, কষ্টদায়ক কথা শুনে আল্লাহর চেয়ে বেশি ধৈর্যশীল কেউ নেই। মানুষ তাঁর জন্য সন্তান সাব্যস্ত করে, তবু তিনি তাদের সুস্থতা ও রিযিক দান করেন।"}] },
];
